  function b64ToBytes(b64: string): number[] {
    const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    const lookup: number[] = new Array(256).fill(-1);
    for (let i = 0; i < chars.length; i++) lookup[chars.charCodeAt(i)] = i;
    const clean = b64.replace(/[^A-Za-z0-9+\/]/g, "");
    const len = clean.length;
    const out: number[] = [];
    for (let i = 0; i < len; i += 4) {
      const a = lookup[clean.charCodeAt(i)];
      const b = lookup[clean.charCodeAt(i + 1)];
      const c = i + 2 < len ? lookup[clean.charCodeAt(i + 2)] : 0;
      const d = i + 3 < len ? lookup[clean.charCodeAt(i + 3)] : 0;
      out.push(((a << 2) | (b >> 4)) & 255);
      if (i + 2 < len && clean.charAt(i + 2) !== "=") out.push(((b << 4) | (c >> 2)) & 255);
      if (i + 3 < len && clean.charAt(i + 3) !== "=") out.push(((c << 6) | d) & 255);
    }
    return out;
  }

  function toIl2CppBytes(bytes: number[]): any {
    const SystemByte = Il2Cpp.corlib.class("System.Byte");
    // pass values array directly — avoids "array length does not match fields"
    try {
      return Il2Cpp.array(SystemByte, bytes.map((b) => b & 0xff));
    } catch (e) {
      const arr = Il2Cpp.array(SystemByte, bytes.length);
      for (let i = 0; i < bytes.length; i++) {
        try { arr.set(i, bytes[i] & 0xff); } catch (_) {}
      }
      return arr;
    }
  }

  function makeEmptyTexture2D(): any {
    // Texture2D.new(2,2) throws "array length does not match number of fields" on some builds
    const tex = Texture2D.alloc();
    try {
      tex.method(".ctor", 2).invoke(2, 2);
      return tex;
    } catch (e1) {}
    try {
      const fmt = TextureFormat.field("RGBA32").value;
      tex.method(".ctor", 4).invoke(2, 2, fmt, false);
      return tex;
    } catch (e2) {}
    try {
      const fmt = TextureFormat.field("RGBA32").value;
      tex.method(".ctor", 5).invoke(2, 2, fmt, false, false);
      return tex;
    } catch (e3) {
      console.log("[mestro] Texture2D ctor failed: " + e3);
      return null;
    }
  }

  let logoFailedAt = 0;
  function buildLogoTexture(): any {
    if (cachedLogoTex && !cachedLogoTex.isNull()) return cachedLogoTex;
    if (Date.now() - logoFailedAt < 10000) return null;
    logoFailedAt = Date.now();
    if (!ImageConversion) {
      logV("[mestro] ImageConversion missing — logo skipped");
      return null;
    }
    try {
      const bytes = b64ToBytes(LOGO_PNG_B64);
      if (!bytes || bytes.length < 100) {
        console.log("[mestro] embedded logo decode failed");
        return null;
      }
      const byteArr = toIl2CppBytes(bytes);
      const tex = makeEmptyTexture2D();
      if (!tex) return null;

      let loaded = false;
      try {
        const r = ImageConversion.method("LoadImage", 2).invoke(tex, byteArr);
        loaded = r === true || r === 1 || r === "true";
      } catch (e) {
        console.log("[mestro] LoadImage(2) err: " + e);
      }
      if (!loaded) {
        try {
          ImageConversion.method("LoadImage", 3).invoke(tex, byteArr, false);
          loaded = true;
        } catch (e) {
          console.log("[mestro] LoadImage failed: " + e);
          return null;
        }
      }
      try { tex.method("Apply", 0).invoke(); } catch (_) {}
      try { tex.method("Apply", 2).invoke(false, false); } catch (_) {}
      cachedLogoTex = tex;
      console.log("[mestro] GRO menu logo ready from embed (" + bytes.length + " bytes) — made by mestro");
      return tex;
    } catch (e) {
      console.log("[mestro] buildLogoTexture error: " + e);
      return null;
    }
  }

