  let playerRefs: any = null;
  let nextPlayerRetry = 0;

  function buildPlayer(kind: string, o: any, leftField: string, rightField: string) {
    return {
      kind: kind,
      obj: o,
      leftHand: o.field(leftField).value,
      rightHand: o.field(rightField).value,
      head: o.field("headCollider").value,
      rb: o.field("playerRigidBody").value,
      setMove: (v: boolean): boolean => {
        try {
          o.field("disableMovement").value = v;
          return true;
        } catch (e) {
          return false;
        }
      }
    };
  }


  let playerScan = "n/a";

  function scanInstances(klass: any): any[] {
    if (!klass) return [];
    try {
      return toJsArray(Il2Cpp.gc.choose(klass));
    } catch (e) {
      playerScan += "!gc";
      console.log("[Scan] gc.choose failed: " + e);
      return [];
    }
  }

  function tryBuild(kind: string, candidates: any[], leftField: string, rightField: string): any {
    for (let i = 0; i < candidates.length; i++) {
      const c = candidates[i];
      if (!c || (c.isNull && c.isNull())) continue;
      try {
        const b = buildPlayer(kind, c, leftField, rightField);
        if (b.rb && !b.rb.isNull()) return b;
      } catch (e) {}
    }
    return null;
  }

  function playerFromRig(): any {
    try {
      const ctx = LocalPlayerContextClass.method("get_Instance").invoke();
      if (!ctx || ctx.isNull()) {
        playerScan += "!ctx";
        return null;
      }
      const rig = ctx.method("get_HardwareRig").invoke();
      if (!rig || rig.isNull()) {
        playerScan += "!rig";
        return null;
      }
      const t = rig.method("get_transform").invoke();
      const root = t.method("get_root").invoke();
      if (!root || root.isNull()) {
        playerScan += "!root";
        return null;
      }

      try {
        hardwareRig = rig;
      } catch (e) {}

      return {
        kind: "rig",
        obj: root,
        leftHand: null,
        rightHand: null,
        head: null,
        rb: null,
        setMove: (v: boolean): boolean => false
      };
    } catch (e) {
      playerScan += "!rigEx";
      console.log("[Scan] playerFromRig failed: " + e);
      return null;
    }
  }

  function resolvePlayer() {
    if (playerRefs) {
      try {
        if (playerRefs.obj && playerRefs.obj.isNull()) playerRefs = null;
      } catch (e) {
        playerRefs = null;
      }
      if (playerRefs) return playerRefs;
    }
    const now = Date.now();
    if (now < nextPlayerRetry) return null;
    nextPlayerRetry = now + 2000;

    playerScan = "";

    playerRefs = playerFromRig();
    if (playerRefs) {
      logV("[mestro] player = " + playerRefs.kind + " [" + playerScan + "]");
      return playerRefs;
    }

    if (!LocomotionClass) {
      playerScan += " noClass";
      return null;
    }

    const c1 = scanInstances(LocomotionClass);
    playerScan += " n" + c1.length;
    playerRefs = tryBuild("GorillaLocomotion", c1, "leftHandFollower", "rightHandFollower");
    if (playerRefs) {
      logV("[mestro] player = GorillaLocomotion (" + c1.length + " candidates)");
      return playerRefs;
    }

    if (LocoPlusClass) {
      const c2 = scanInstances(LocoPlusClass);
      playerScan += " p" + c2.length;
      playerRefs = tryBuild("GorillaLocomotionPlus", c2, "leftController", "rightController");
      if (playerRefs) {
        logV("[mestro] player = GorillaLocomotionPlus (" + c2.length + " candidates)");
        return playerRefs;
      }
    }

    playerRefs = null;
    console.log("[mestro] player scan failed: " + playerScan);
    return null;
  }

  let hardwareRig: any = null;
  let nextRigRetry = 0;

  function getRig() {
    if (hardwareRig && !hardwareRig.isNull()) return hardwareRig;
    const now = Date.now();
    if (now < nextRigRetry) return null;
    nextRigRetry = now + 2000;

    try {
      const p = resolvePlayer();
      if (p) {
        const r = p.obj.field("hardwareRig").value;
        if (r && !r.isNull()) {
          hardwareRig = r;
          logV("[mestro] HardwareRig found on locomotion");
          return r;
        }
      }
    } catch (e) {}

  
    try {
      const ctx = LocalPlayerContextClass.method("get_Instance").invoke();
      if (ctx && !ctx.isNull()) {
        const rig = ctx.method("get_HardwareRig").invoke();
        if (rig && !rig.isNull()) {
          hardwareRig = rig;
          logV("[mestro] local HardwareRig found");
          return rig;
        }
      }
    } catch (e) {}
    return null;
  }

  function rigHand(isLeft: boolean) {
    const rig = getRig();
    if (!rig) return null;
    try {
      const h = rig.field(isLeft ? "leftHand" : "rightHand").value;
      if (h && !h.isNull()) return h;
    } catch (e) {}
    return null;
  }

  function handTransform(isLeft: boolean) {
    const p = resolvePlayer();
    if (p) {
      const h = isLeft ? p.leftHand : p.rightHand;
      if (h && !h.isNull()) return h;
    }
    const hand = rigHand(isLeft);
    if (hand) {
      try {
        return hand.method("get_transform").invoke();
      } catch (e) {}
    }
    return null;
  }

  let leftDeviceId = 0;
  let rightDeviceId = 0;
  let xrUsable = false;

  function readDeviceId(node: number): number {
    try {
      const dev = InputDevicesClass.method("GetDeviceAtXRNode", 1).invoke(node);
      if (!dev || (dev.isNull && dev.isNull())) return 0;
      if (!dev.method("get_isValid").invoke()) return 0;
      return Number(dev.method("get_deviceId").invoke());
    } catch (e) {
      return 0;
    }
  }

  function refreshXRDevices() {
    leftDeviceId = readDeviceId(4); // XRNode.LeftHand
    rightDeviceId = readDeviceId(5); // XRNode.RightHand
    xrUsable = leftDeviceId !== 0 || rightDeviceId !== 0;
  }

  function xrFeature(deviceId: number, usage: any): boolean {
    if (!deviceId) return false;
    try {
      const ok = tryFeatureMethod.invoke(deviceId, usage, featureBuffer);
      if (!ok) return false;
      return featureBuffer.readU8() !== 0;
    } catch (e) {
      return false;
    }
  }

  // continuous trigger pull 0..1 (hold fly needs axis, not just press edge)
  let leftTriggerAxis = 0;
  let rightTriggerAxis = 0;
  const TRIGGER_HOLD = 0.18;

  function readTriggerAxis(controller: number): number {
    // OVRInput.Axis1D.PrimaryIndexTrigger ≈ 1 on many builds; also try 4
    const axes = [1, 4, 0];
    for (let i = 0; i < axes.length; i++) {
      try {
        const v = OVRInputClass.method("Get", 2).invoke(axes[i], controller);
        const n = typeof v === "number" ? v : Number(v);
        if (!isNaN(n) && n > 0.01) return Math.max(0, Math.min(1, n));
      } catch (_) {}
    }
    // Button near-press fallbacks
    try {
      if (OVRInputClass.method("Get", 2).invoke(8192, controller === 1 ? -2147483648 : -2147483648)) return 1;
    } catch (_) {}
    try {
      if (controller === 2 && OVRInputClass.method("Get", 2).invoke(2097152, -2147483648)) return 1;
      if (controller === 1 && OVRInputClass.method("Get", 2).invoke(8192, -2147483648)) return 1;
    } catch (_) {}
    return 0;
  }

  function readOVRInput() {
    try { OVRInputClass.method("Update").invoke(); } catch (_) {}
    leftPrimary = !!OVRInputClass.method("Get", 2).invoke(1, 1);
    leftSecondary = !!OVRInputClass.method("Get", 2).invoke(2, 1);
    rightPrimary = !!OVRInputClass.method("Get", 2).invoke(1, 2);
    rightSecondary = !!OVRInputClass.method("Get", 2).invoke(2, 2);
    leftGrab = !!OVRInputClass.method("Get", 2).invoke(16384, -2147483648);
    rightGrab = !!OVRInputClass.method("Get", 2).invoke(4194304, -2147483648);
    leftTriggerAxis = readTriggerAxis(1);
    rightTriggerAxis = readTriggerAxis(2);
    leftTrigger = leftTriggerAxis >= TRIGGER_HOLD;
    rightTrigger = rightTriggerAxis >= TRIGGER_HOLD;
  }

  function readInput() {
    if (frameCount === 1 || frameCount % 120 === 0) refreshXRDevices();

    leftTriggerAxis = 0;
    rightTriggerAxis = 0;
    let got = false;

    const lh = rigHand(true);
    const rh = rigHand(false);
    if (lh && rh) {
      try {
        leftPrimary = !!lh.method("get_PrimaryButtonPressed").invoke();
        leftSecondary = !!lh.method("get_SecondaryButtonPressed").invoke();
        leftGrab = !!lh.method("get_GripPressed").invoke();
        rightPrimary = !!rh.method("get_PrimaryButtonPressed").invoke();
        rightSecondary = !!rh.method("get_SecondaryButtonPressed").invoke();
        rightGrab = !!rh.method("get_GripPressed").invoke();
        // TriggerPressed can be edge-only — also try float TriggerValue / axis
        try {
          leftTriggerAxis = Number(lh.method("get_TriggerValue").invoke()) || 0;
        } catch (_) {
          leftTrigger = !!lh.method("get_TriggerPressed").invoke();
          if (leftTrigger) leftTriggerAxis = 1;
        }
        try {
          rightTriggerAxis = Number(rh.method("get_TriggerValue").invoke()) || 0;
        } catch (_) {
          rightTrigger = !!rh.method("get_TriggerPressed").invoke();
          if (rightTrigger) rightTriggerAxis = 1;
        }
        got = true;
      } catch (e) {}
    }

    if (xrUsable) {
      leftPrimary = leftPrimary || xrFeature(leftDeviceId, USAGE_PRIMARY);
      leftSecondary = leftSecondary || xrFeature(leftDeviceId, USAGE_SECONDARY);
      leftGrab = leftGrab || xrFeature(leftDeviceId, USAGE_GRIP);
      rightPrimary = rightPrimary || xrFeature(rightDeviceId, USAGE_PRIMARY);
      rightSecondary = rightSecondary || xrFeature(rightDeviceId, USAGE_SECONDARY);
      rightGrab = rightGrab || xrFeature(rightDeviceId, USAGE_GRIP);
      // XR trigger axis if available
      try {
        const lt = xrFeatureAxis(leftDeviceId, USAGE_TRIGGER);
        const rt = xrFeatureAxis(rightDeviceId, USAGE_TRIGGER);
        if (lt > leftTriggerAxis) leftTriggerAxis = lt;
        if (rt > rightTriggerAxis) rightTriggerAxis = rt;
      } catch (_) {
        if (xrFeature(leftDeviceId, USAGE_TRIGGER)) leftTriggerAxis = Math.max(leftTriggerAxis, 1);
        if (xrFeature(rightDeviceId, USAGE_TRIGGER)) rightTriggerAxis = Math.max(rightTriggerAxis, 1);
      }
      got = true;
    }

    // merge OVR axis (max) so hold stays true while squeezed
    try {
      const prevL = leftTriggerAxis;
      const prevR = rightTriggerAxis;
      const prevLP = leftPrimary, prevLS = leftSecondary, prevLG = leftGrab;
      const prevRP = rightPrimary, prevRS = rightSecondary, prevRG = rightGrab;
      readOVRInput();
      leftTriggerAxis = Math.max(prevL, leftTriggerAxis);
      rightTriggerAxis = Math.max(prevR, rightTriggerAxis);
      leftPrimary = prevLP || leftPrimary;
      leftSecondary = prevLS || leftSecondary;
      leftGrab = prevLG || leftGrab;
      rightPrimary = prevRP || rightPrimary;
      rightSecondary = prevRS || rightSecondary;
      rightGrab = prevRG || rightGrab;
    } catch (e) {}

    leftTrigger = leftTriggerAxis >= TRIGGER_HOLD;
    rightTrigger = rightTriggerAxis >= TRIGGER_HOLD;
  }

  function xrFeatureAxis(deviceId: number, usage: string): number {
    if (!deviceId) return 0;
    try {
      // try float feature
      const held = Memory.alloc(4);
      // fallback bool path only
      if (xrFeature(deviceId, usage)) return 1;
    } catch (_) {}
    return 0;
  }

  function disableCollider(obj) {
    try {
      const collider = getComponent(obj, Collider);
      if (collider && !collider.isNull()) collider.method("set_enabled").invoke(false);
    } catch (e) {}
  }

  function applyVisibleMaterial(obj: any, colorArr: [number, number, number, number]) {
    try {
      const renderer = getComponent(obj, Renderer);
      if (!renderer || renderer.isNull()) return;
      if (colorArr[3] == 0) {
        try { renderer.method("set_enabled").invoke(false); } catch (_) {}
        return;
      }
      try { renderer.method("set_enabled").invoke(true); } catch (_) {}
      const material = renderer.method("get_material").invoke();
      if (!material || material.isNull()) return;
      // Unlit so panel is visible outdoors / in VR (Standard lit often looks black)
      try {
        if (MenuShader && !MenuShader.isNull()) {
          material.method("set_shader").invoke(MenuShader);
        }
      } catch (_) {}
      const solid: [number, number, number, number] = [
        Math.max(0.05, colorArr[0]),
        Math.max(0.05, colorArr[1]),
        Math.max(0.05, colorArr[2]),
        1.0
      ];
      try { material.method("set_color").invoke(solid); } catch (_) {}
      try { material.method("SetColor", 2).invoke(Il2Cpp.string("_Color"), solid); } catch (_) {}
      try { material.method("SetColor", 2).invoke(Il2Cpp.string("_BaseColor"), solid); } catch (_) {}
    } catch (_) {}
  }

  function createObject(
    pos = zeroVector,
    rot = identityQuaternion,
    scale = oneVector,
    primitiveType: number = 3,
    colorArr: [number, number, number, number] = [1, 1, 1, 1],
    parent = null
  ) {
    const obj = GameObject.method("CreatePrimitive").invoke(primitiveType);
    applyVisibleMaterial(obj, colorArr);

    try {
      const transform = getTransform(obj);
      if (parent != null) {
        try {
          transform.method("SetParent", 2).invoke(parent, false);
        } catch (_) {}
        disableCollider(obj);
      }
      transform.method("set_position").invoke(pos);
      transform.method("set_rotation").invoke(rot);
      transform.method("set_localScale").invoke(scale);
    } catch (_) {}
    return obj;
  }

  function safeTrigger(obj: any) {
    try {
      const c = getComponent(obj, BoxCollider);
      if (c && !c.isNull()) c.method("set_isTrigger").invoke(true);
    } catch (_) {}
  }

  function safeDestroyComp(obj: any, type: any) {
    try {
      const c = getComponent(obj, type);
      if (c && !c.isNull()) Destroy(c);
    } catch (_) {}
  }

  function renderMenuText(canvasObject, text: string = "", color: [number, number, number, number] = [1, 1, 1, 1], pos = zeroVector, size = oneVector) {
    const go = createObject(zeroVector, identityQuaternion, oneVector, 3, [0, 0, 0, 0], getTransform(canvasObject));
    const title = addComponent(go, Text);
    safeTrigger(go);
    title.method("set_text").invoke(Il2Cpp.string(text));
    try {
      const menuFont = getMenuFont();
      if (menuFont) title.method("set_font").invoke(menuFont);
    } catch (_) {}
    title.method("set_fontSize").invoke(1);
    title.method("set_color").invoke(color);
    title.method("set_fontStyle").invoke(2);
    title.method("set_alignment").invoke(4);
    title.method("set_resizeTextForBestFit").invoke(true);
    title.method("set_resizeTextMinSize").invoke(0);

    const rectTransform = getComponent(title, RectTransform);
    rectTransform.method("set_sizeDelta").invoke(size);
    rectTransform.method("set_position").invoke(pos);
    rectTransform.method("set_rotation").invoke(Quaternion.method("Euler").invoke(180.0, 90.0, 90.0));
    return title;
  }

  let titleObj: any = null;

  function buildTitle() {
    let s = menuName;
    s +=
      (currentCategory === CAT_ITEMS
        ? selectedItem
          ? ` - Sel <color=yellow>${selectedItem.id}</color>`
          : ` - Items <color=grey>[</color> ${itemList.length} <color=grey>]</color>`
        : "") +
      ` - Page <color=grey>[</color> ${currentPage + 1} <color=grey>]</color>`;
    return s;
  }

  function updateTitle() {
    if (!titleObj || titleObj.isNull()) return;
    try {
      titleObj.method("set_text").invoke(Il2Cpp.string(buildTitle()));
    } catch (e) {}
  }

  function refreshButtons() {
    try {
      for (let i = 0; i < buttonsList.length; i++) {
        updateButtonColor(buttonsList[i].obj, buttonsList[i].data);
      }
      updateTitle();
    } catch (e) {}
  }

  interface ButtonInfoConfig {
    buttonText: string;
    method?: () => void;
    enableMethod?: () => void;
    disableMethod?: () => void;
    keepOn?: boolean;
    enabled?: boolean;
    item?: ItemEntry;
    reload?: boolean;
  }

  class ButtonInfo {
    buttonText: string;
    method?: () => void;
    enableMethod?: () => void;
    disableMethod?: () => void;
    keepOn: boolean;
    enabled: boolean;
    item?: ItemEntry;
    reload: boolean;

    constructor(config: ButtonInfoConfig) {
      this.buttonText = config.buttonText;
      this.method = config.method;
      this.enableMethod = config.enableMethod;
      this.disableMethod = config.disableMethod;
      this.item = config.item;
      this.keepOn = config.keepOn === undefined || config.keepOn === null ? true : config.keepOn;
      this.enabled = config.enabled === undefined || config.enabled === null ? false : config.enabled;
      this.reload = config.reload === undefined || config.reload === null ? true : config.reload;
    }
  }

  function updateButtonColor(button, buttonData) {
    try {
      const renderer = getComponent(button, Renderer);
      if (!renderer) return;
      const material = renderer.method("get_material").invoke();
      const on = !!buttonData.enabled || (!!buttonData.item && buttonData.item === selectedItem);
      material.method("set_color").invoke(on ? buttonPressedColor : buttonColor);
    } catch (e) {}
  }

  const PAGE_SIZE = 7;
  const ITEM_BUTTONS_FIXED = 2;
  // TMC base scale × MENU_SCALE (keeps bg + mods glued together)
  const MENU_BASE_X = 0.10;
  const MENU_BASE_Y = 0.30;
  const MENU_BASE_Z = 0.3825;
  let MENU_SCALE = 0.90;

  function setMenuRootScale() {
    if (!menu) return;
    try {
      const menuTransform = getTransform(menu);
      menuTransform.method("set_localScale").invoke([
        MENU_BASE_X * MENU_SCALE,
        MENU_BASE_Y * MENU_SCALE,
        MENU_BASE_Z * MENU_SCALE
      ]);
    } catch (e) {}
  }

  // ---- real color wheel (HSV) ----
  // outer ring = hue, inner = saturation/value — we expose hue + sat + val controls
  let menuHue = 280;        // 0-360 like the iOS wheel
  let menuSat = 0.75;       // 0-1
  let menuVal = 0.55;       // 0-1 base brightness for panel
  let animBgOn = false;     // OFF — animation caused lag + disappearing panel
  let menuBgObj: any = null;
  let menuBgMat: any = null;

  function hsvToRgb(h: number, s: number, v: number): [number, number, number] {
    h = ((h % 360) + 360) % 360;
    const c = v * s;
    const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
    const m = v - c;
    let r = 0, g = 0, b = 0;
    if (h < 60) { r = c; g = x; b = 0; }
    else if (h < 120) { r = x; g = c; b = 0; }
    else if (h < 180) { r = 0; g = c; b = x; }
    else if (h < 240) { r = 0; g = x; b = c; }
    else if (h < 300) { r = x; g = 0; b = c; }
    else { r = c; g = 0; b = x; }
    return [r + m, g + m, b + m];
  }

  function rebuildColorsFromWheel() {
    // solid dark panel — always opaque so it never washes out outdoors
    const bg = hsvToRgb(menuHue, menuSat * 0.9, Math.min(0.28, menuVal * 0.45));
    bgColor = [bg[0], bg[1], bg[2], 1.0];

    // text — pure bright white for max contrast on bright maps
    textColor = [1.0, 1.0, 1.0, 1.0];

    // buttons — mid sat, solid
    const btn = hsvToRgb(menuHue, menuSat, Math.max(0.35, menuVal * 0.65));
    buttonColor = [btn[0], btn[1], btn[2], 1.0];

    // pressed — brighter solid
    const pr = hsvToRgb(menuHue, Math.min(1, menuSat + 0.1), Math.min(1, menuVal + 0.3));
    buttonPressedColor = [pr[0], pr[1], pr[2], 1.0];
  }

  function setObjectColor(obj: any, col: [number, number, number, number]) {
    if (!obj || obj.isNull()) return;
    try {
      const renderer = getComponent(obj, Renderer);
      if (!renderer || renderer.isNull()) return;
      const material = renderer.method("get_material").invoke();
      if (!material || material.isNull()) return;
      material.method("set_color").invoke(col);
    } catch (e) {}
  }

  // live recolor without destroying layout
  function applyColorsLive() {
    rebuildColorsFromWheel();
    // background
    if (menuBgObj && !menuBgObj.isNull()) {
      setObjectColor(menuBgObj, bgColor);
      try {
        const renderer = getComponent(menuBgObj, Renderer);
        if (renderer && !renderer.isNull()) {
          menuBgMat = renderer.method("get_material").invoke();
        }
      } catch (e) {}
    }
    // all buttons currently on screen
    for (let i = 0; i < buttonsList.length; i++) {
      try {
        updateButtonColor(buttonsList[i].obj, buttonsList[i].data);
      } catch (e) {}
    }
    logV("[Color] H=" + menuHue.toFixed(0) + " S=" + menuSat.toFixed(2) + " V=" + menuVal.toFixed(2));
  }

  function nudgeHue(delta: number) {
    menuHue = ((menuHue + delta) % 360 + 360) % 360;
    applyColorsLive();
  }

  function nudgeSat(delta: number) {
    menuSat = Math.max(0.05, Math.min(1.0, menuSat + delta));
    applyColorsLive();
  }

  function nudgeVal(delta: number) {
    menuVal = Math.max(0.15, Math.min(1.0, menuVal + delta));
    applyColorsLive();
  }

  // animated moving background — shifts brightness + slight hue drift, always follows wheel color
  function tickMenuBackground() {
    if (!animBgOn || !menuOpen) return;
    // animate every 3rd frame only — material set_color is expensive
    if ((frameCount & 3) !== 0) return;
    if (!menuBgMat || menuBgMat.isNull()) {
      if (menuBgObj && !menuBgObj.isNull()) {
        try {
          const renderer = getComponent(menuBgObj, Renderer);
          if (renderer && !renderer.isNull()) menuBgMat = renderer.method("get_material").invoke();
        } catch (e) {}
      }
      if (!menuBgMat || menuBgMat.isNull()) return;
    }
    try {
      const t = time || (Date.now() / 1000);
      const pulse = 0.5 + 0.5 * Math.sin(t * 1.7);
      const shimmer = Math.sin(t * 0.6) * 12;
      const h = menuHue + shimmer;
      const v = menuVal * 0.28 + pulse * menuVal * 0.22;
      const s = menuSat * (0.7 + pulse * 0.25);
      const rgb = hsvToRgb(h, s, v);
      menuBgMat.method("set_color").invoke([rgb[0], rgb[1], rgb[2], 1.0]);
    } catch (e) {}
  }

  // legacy name kept so old settings buttons still compile if referenced
  let themeIndex = 0;
  function applyTheme(_i: number) {
    // map old theme steps onto hue wheel positions
    const hues = [280, 140, 30, 210, 0, 0];
    const sats = [0.75, 0.75, 0.8, 0.7, 0.85, 0.05];
    themeIndex = ((themeIndex + 1) % hues.length + hues.length) % hues.length;
    menuHue = hues[themeIndex];
    menuSat = sats[themeIndex];
    menuVal = themeIndex === 5 ? 0.4 : 0.55;
    applyColorsLive();
  }

  function applyMenuScale(delta: number) {
    MENU_SCALE = Math.max(0.55, Math.min(1.8, MENU_SCALE + delta));
    setMenuRootScale();
    logV("[Settings] scale x" + MENU_SCALE.toFixed(2));
  }

  // init colors once
  rebuildColorsFromWheel();

  let menuBuilding = false;
  let menuBuildStartedAt = 0;

  function renderMenu() {
    if (menuBuilding) {
      // if stuck, don't soft-lock forever
      if (Date.now() - menuBuildStartedAt < 800) return;
      menuBuilding = false;
    }
    menuBuilding = true;
    menuBuildStartedAt = Date.now();
    try {
      renderMenuInner();
    } catch (e) {
      logV("[mestro] renderMenu CRASH blocked: " + e);
      try {
        if (menu != null) {
          const old = menu;
          menu = null;
          Destroy(old);
        }
      } catch (_) {}
      menu = null;
      buttonsList = [];
    } finally {
      menuBuilding = false;
    }
  }

  const NEON_BLUE: [number, number, number, number] = [0.1, 0.45, 1.0, 1.0];
  // side panels lean inward like the reference photo
  function sideRot(deg: number): any {
    try { return Quaternion.method("Euler").invoke(0, 0, deg); } catch (_) { return identityQuaternion; }
  }
  const TITLE_CYAN: [number, number, number, number] = [0.35, 0.8, 1.0, 1.0];

  function renderMenuInner() {
    buttonsList = [];

    if (menu != null) {
      try {
        const old = menu;
        menu = null;
        Destroy(old);
      } catch (_) {}
    }

    if (currentCategory < 0 || currentCategory >= buttons.length) currentCategory = CAT_HOME;
    const cat = buttons[currentCategory] || buttons[CAT_HOME] || [];
    const lastPage = Math.max(0, Math.ceil(cat.length / PAGE_SIZE) - 1);
    if (currentPage > lastPage) currentPage = lastPage;

    menu = createObject(zeroVector, identityQuaternion, [0.1, 0.3, 0.3825], 3, [0, 0, 0, 0]);
    disableCollider(menu);
    safeDestroyComp(menu, BoxCollider);

    // solid panel — slightly thicker so it always reads in VR
    const panelCol: [number, number, number, number] = [bgColor[0], bgColor[1], bgColor[2], 1.0];
    const menuBackground = createObject(
      [0.08, 0, 0],
      identityQuaternion,
      [0.14, 1.05, 1.05],
      3,
      panelCol,
      getTransform(menu)
    );
    safeDestroyComp(menuBackground, BoxCollider);
    menuBgObj = menuBackground;
    menuBgMat = null;
    try {
      applyVisibleMaterial(menuBackground, panelCol);
      const br = getComponent(menuBackground, Renderer);
      if (br && !br.isNull()) {
        try { br.method("set_enabled").invoke(true); } catch (_) {}
        menuBgMat = br.method("get_material").invoke();
      }
      logV("[mestro] background panel on");
    } catch (e) {
      logV("[mestro] background mat: " + e);
    }

    // logo disabled for stability (LoadImage native crashes on some Quest builds)

    let canvasObject: any = null;
    try {
      canvasObject = createObject(zeroVector, identityQuaternion, oneVector, 3, [0, 0, 0, 0], getTransform(menu));
      safeDestroyComp(canvasObject, BoxCollider);
      const canvas = addComponent(canvasObject, Canvas);
      try { canvas.method("set_renderMode").invoke(2); } catch (_) {}
      try {
        const canvasScaler = addComponent(canvasObject, CanvasScaler);
        try { canvasScaler.method("set_dynamicPixelsPerUnit").invoke(1000.0); } catch (_2) {}
      } catch (_) {}
      // GraphicRaycaster skipped — not needed for our pointer, caused some crashes
      logV("[mestro] canvas ok");
    } catch (e) {
      console.log("[mestro] canvas setup FAILED: " + e);
      // last resort: still try a bare object for text parent
      try {
        canvasObject = createObject(zeroVector, identityQuaternion, oneVector, 3, [0, 0, 0, 0], getTransform(menu));
      } catch (_2) {
        logV("[mestro] no canvas parent — abort build");
        return;
      }
    }

    // home
    const homeButton = createObject([0.1, -0.175, -0.225], identityQuaternion, [0.09, 0.09, 0.09], 3, buttonColor, getTransform(menu));
    try { homeButton.method("set_name").invoke(Il2Cpp.string("@Home")); } catch (_) {}
    safeTrigger(homeButton);
    renderMenuText(canvasObject, "<", textColor, [0.11, -0.175, -0.225], [0.15, 0.15]);
    buttonsList.push({
      obj: homeButton,
      data: {
        buttonText: "<",
        keepOn: false,
        method: () => {
          currentCategory = CAT_HOME;
          currentPage = 0;
          logV("[mestro] → home");
        }
      }
    });

    // Leave
    const leaveButton = createObject([0.1, -0.22, 0.225], identityQuaternion, [0.09, 0.36, 0.07], 3, buttonColor, getTransform(menu));
    try { leaveButton.method("set_name").invoke(Il2Cpp.string("@Leave")); } catch (_) {}
    safeTrigger(leaveButton);
    renderMenuText(canvasObject, "Leave", textColor, [0.11, -0.22, 0.225], [0.36, 0.09]);
    buttonsList.push({
      obj: leaveButton,
      data: { buttonText: "Leave", keepOn: false, method: () => leaveSession() }
    });

    // New Room
    const newRoomButton = createObject([0.1, 0.22, 0.225], identityQuaternion, [0.09, 0.36, 0.07], 3, buttonColor, getTransform(menu));
    try { newRoomButton.method("set_name").invoke(Il2Cpp.string("@NewRoom")); } catch (_) {}
    safeTrigger(newRoomButton);
    renderMenuText(canvasObject, "New Room", textColor, [0.11, 0.22, 0.225], [0.36, 0.09]);
    buttonsList.push({
      obj: newRoomButton,
      data: { buttonText: "New Room", keepOn: false, method: () => newRoomJoin() }
    });

    titleObj = renderMenuText(canvasObject, buildTitle(), TITLE_CYAN, [0.11, 0, 0.166], [0.95, 0.1]);

    createObject([0.1, 0.6, 0], sideRot(25), [0.07, 0.34, 0.52], 3, NEON_BLUE, getTransform(menu));
    const pagePrev = createObject([0.1, 0.6, 0], sideRot(25), [0.09, 0.32, 0.5], 3, buttonColor, getTransform(menu));
    try { pagePrev.method("set_name").invoke(Il2Cpp.string("@PreviousPage")); } catch (_) {}
    safeTrigger(pagePrev);
    renderMenuText(canvasObject, "<", textColor, [0.12, 0.6, 0], [0.12, 0.12]);
    buttonsList.push({
      obj: pagePrev,
      data: {
        buttonText: "PreviousPage",
        keepOn: false,
        method: () => {
          currentPage--;
          if (currentPage < 0) currentPage = lastPage;
        }
      }
    });

    createObject([0.1, -0.6, 0], sideRot(-25), [0.07, 0.34, 0.52], 3, NEON_BLUE, getTransform(menu));
    const pageNext = createObject([0.1, -0.6, 0], sideRot(-25), [0.09, 0.32, 0.5], 3, buttonColor, getTransform(menu));
    try { pageNext.method("set_name").invoke(Il2Cpp.string("@NextPage")); } catch (_) {}
    safeTrigger(pageNext);
    renderMenuText(canvasObject, ">", textColor, [0.12, -0.6, 0], [0.12, 0.12]);
    buttonsList.push({
      obj: pageNext,
      data: {
        buttonText: "NextPage",
        keepOn: false,
        method: () => {
          currentPage++;
          currentPage %= lastPage + 1;
        }
      }
    });

    // mod rows
    let i = 0;
    const targetMods = cat.slice(currentPage * PAGE_SIZE, currentPage * PAGE_SIZE + PAGE_SIZE);
    for (let mi = 0; mi < targetMods.length; mi++) {
      try {
        const buttonData = targetMods[mi];
        const z = 0.13 - i * 0.04;
        createObject([0.1, 0, z], identityQuaternion, [0.07, 0.915, 0.095], 3, NEON_BLUE, getTransform(menu));
        const button = createObject([0.105, 0, z], identityQuaternion, [0.09, 0.9, 0.08], 3, buttonColor, getTransform(menu));
        try { button.method("set_name").invoke(Il2Cpp.string("@" + buttonData.buttonText)); } catch (_) {}
        safeTrigger(button);
        try {
          renderMenuText(canvasObject, buttonData.buttonText, textColor, [0.11, 0, z], [1, 0.1]);
        } catch (_) {}
        try { updateButtonColor(button, buttonData); } catch (_) {}
        buttonsList.push({ obj: button, data: buttonData });
        i++;
      } catch (rowErr) {
        console.log("[mestro] row skip: " + rowErr);
      }
    }

    try { setMenuRootScale(); } catch (_) {}
    try {
      if (attachMenuToHand()) logV("[mestro] menu parented to hand");
      else {
        recenterMenu();
        logV("[mestro] menu world-placed (no hand yet)");
      }
    } catch (e) {
      logV("[mestro] attach: " + e);
    }
    logV("[mestro] menu built cat=" + currentCategory + " btns=" + buttonsList.length);
  }

  function renderReference() {
    const rightHand = handTransform(false);
    if (!rightHand) return;

    reference = createObject(zeroVector, identityQuaternion, [0.01, 0.01, 0.01], 0, [0.2, 0.6, 1.0, 1.0], rightHand);
    referenceCollider = getComponent(reference, Collider);

    getTransform(reference).method("set_localPosition").invoke([0.01, -0.117, 0.05]);
    if (referenceCollider && !referenceCollider.isNull()) {
      referenceCollider.method("set_isTrigger").invoke(true);
    }
    addComponent(reference, Rigidbody).method("set_isKinematic").invoke(true);
  }

  let menuParented = false;

  function attachMenuToHand() {
    if (!menu) return false;
    const hand = handTransform(true) || handTransform(false);
    if (!hand) return false;
    try {
      const mt = getTransform(menu);
      // PARENT to hand so it never floats in the world as debris
      try {
        mt.method("SetParent", 2).invoke(hand, false);
      } catch (_) {
        try { mt.method("SetParent", 1).invoke(hand); } catch (_2) {}
      }
      // local offset in front of palm
      try {
        mt.method("set_localPosition").invoke(v3(0.12, 0.05, -0.08));
      } catch (_) {
        try { mt.method("set_localPosition").invoke([0.12, 0.05, -0.08]); } catch (_2) {}
      }
      try {
        mt.method("set_localRotation").invoke(identityQuaternion);
      } catch (_) {}
      try { setMenuRootScale(); } catch (_) {}
      menuParented = true;
      return true;
    } catch (e) {
      console.log("[mestro] attach hand fail: " + e);
      return false;
    }
  }

  function recenterMenu() {
    // prefer parenting (follows free); fallback world copy
    if (attachMenuToHand()) return;
    if (!menu) return;
    const leftHand = handTransform(true) || handTransform(false);
    if (!leftHand) return;
    try {
      const menuTransform = getTransform(menu);
      menuTransform.method("set_position").invoke(leftHand.method("get_position").invoke());
      menuTransform.method("set_rotation").invoke(leftHand.method("get_rotation").invoke());
    } catch (e) {}
  }

  let pendingMenuRebuild = false;
  let pendingDestroyMenu: any = null;

  function reloadMenu() {
    // do not Destroy during button press — schedule only
    if (menu != null) {
      pendingDestroyMenu = menu;
      menu = null;
      buttonsList = [];
      titleObj = null;
      menuBgObj = null;
      menuBgMat = null;
    }
  }

  function flushPendingDestroy() {
    if (pendingDestroyMenu == null) return;
    const old = pendingDestroyMenu;
    pendingDestroyMenu = null;
    menuParented = false;
    try {
      try {
        const t = getTransform(old);
        t.method("SetParent", 2).invoke(null, true);
      } catch (_) {}
      try { old.method("SetActive").invoke(false); } catch (_) {}
      Destroy(old);
    } catch (e) {
      logV("[mestro] Destroy menu: " + e);
    }
  }

  function safeRebuildMenu() {
    pendingMenuRebuild = true;
  }

  // 2-phase rebuild: tick1 destroy, tick2 create — avoids native crash on home/back
  let rebuildPhase = 0; // 0 idle, 1 destroy done waiting, 2 ready to create

  function doMenuRebuild() {
    try {
      if (rebuildPhase === 0) {
        // PHASE 1 — only tear down
        logV("[mestro] rebuild phase1 destroy cat→" + currentCategory);
        try {
          if (menu != null) {
            pendingDestroyMenu = menu;
            menu = null;
          }
          buttonsList = [];
          titleObj = null;
          menuBgObj = null;
          menuBgMat = null;
          flushPendingDestroy();
        } catch (e) {
          logV("[mestro] phase1: " + e);
          menu = null;
          buttonsList = [];
        }
        rebuildPhase = 1;
        // stay pending so next tick creates
        pendingMenuRebuild = true;
        return;
      }

      // PHASE 2 — create fresh
      rebuildPhase = 0;
      pendingMenuRebuild = false;
      logV("[mestro] rebuild phase2 create cat=" + currentCategory);
      if (currentCategory < 0 || currentCategory >= buttons.length) currentCategory = CAT_HOME;
      if (!buttons[currentCategory]) currentCategory = CAT_HOME;
      if (currentCategory === CAT_ITEMS) {
        try { ensureItems(); } catch (_) {}
      }
      if (currentCategory === CAT_SOUNDBOARD) {
        try { rebuildSoundboardButtons(); } catch (_) {}
      }
      if (currentCategory === CAT_PLAYERS) {
        try { rebuildPlayerList(); } catch (_) {}
      }
      menuBuilding = false;
      renderMenu();
      logV("[mestro] rebuild done cat=" + currentCategory + " btns=" + buttonsList.length);
    } catch (e) {
      console.log("[mestro] doMenuRebuild failed: " + e);
      pendingMenuRebuild = false;
      rebuildPhase = 0;
      menu = null;
      buttonsList = [];
      titleObj = null;
      menuBuilding = false;
    }
  }

  const PRESS_RADIUS = 0.065; // larger hitbox so picks actually register in VR

  function checkButtonPressesManual() {
    if (!menu || buttonsList.length === 0 || !reference) return;

    let now = 0;
    try {
      now = Time.method("get_time").invoke();
    } catch (_) {
      now = Date.now() / 1000;
    }
    if (now <= buttonClickDelay) return;

    let refX = 0, refY = 0, refZ = 0;
    try {
      const refPos = getTransform(reference).method("get_position").invoke();
      refX = refPos.field("x").value;
      refY = refPos.field("y").value;
      refZ = refPos.field("z").value;
    } catch (e) {
      return;
    }

    let best = null;
    let bestDist = PRESS_RADIUS;

    for (let i = 0; i < buttonsList.length; i++) {
      const button = buttonsList[i];
      if (!button || !button.obj) continue;
      let btnPos = null;
      try {
        if (button.obj.isNull && button.obj.isNull()) continue;
        btnPos = getTransform(button.obj).method("get_position").invoke();
      } catch (e) {
        continue;
      }

      const dx = refX - btnPos.field("x").value;
      const dy = refY - btnPos.field("y").value;
      const dz = refZ - btnPos.field("z").value;
      // equal weight axes — menu is parented so Z isn't always "depth"
      const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);

      if (dist < bestDist) {
        bestDist = dist;
        best = button;
      }
    }

    if (!best) return;
    buttonClickDelay = now + 0.28;

    const btnData = best.data;
    if (!btnData) return;
    logV("[mestro] press → " + (btnData.buttonText || "?") + " d=" + bestDist.toFixed(3));

    if (btnData.keepOn) {
      try {
        btnData.enabled = !btnData.enabled;
        if (btnData.enabled && btnData.enableMethod) btnData.enableMethod();
        else if (!btnData.enabled && btnData.disableMethod) btnData.disableMethod();
        if (best.obj && !(best.obj.isNull && best.obj.isNull())) {
          updateButtonColor(best.obj, btnData);
        }
      } catch (e) {
        logV("[mestro] toggle btn: " + e);
      }
      return;
    }

    try {
      if (btnData.method) btnData.method();
    } catch (e) {
      logV("[mestro] btn method: " + e);
    }

    if (btnData.reload === false) {
      try { refreshButtons(); } catch (_) {}
      return;
    }

    // NEVER destroy/rebuild on this stack — next tick only
    pendingMenuRebuild = true;
    logV("[mestro] rebuild scheduled (safe)");
  }


  function getRunner() {
    try {
      const r = CommerceClass.method("GetRunner").invoke();
      if (r && !r.isNull()) return r;
    } catch (e) {}
    try {
      const found = sceneInstances(NetworkRunnerClass);
      if (found.length > 0) return found[0];
    } catch (e) {}
    return null;
  }

  function shutdownRunner(runner: any) {
    if (!runner || runner.isNull()) return false;
    const attempts = [
      () => runner.method("Shutdown", 3).invoke(true, 0, true),
      () => runner.method("Shutdown", 3).invoke(false, 0, false),
      () => runner.method("Shutdown", 1).invoke(true),
      () => runner.method("Shutdown", 1).invoke(false),
      () => runner.method("Shutdown", 0).invoke(),
      () => runner.method("Disconnect").invoke()
    ];
    for (let i = 0; i < attempts.length; i++) {
      try {
        attempts[i]();
        logV("[mestro] runner shutdown path " + i);
        return true;
      } catch (e) {}
    }
    return false;
  }

  function leaveSession() {
    try {
      const runner = getRunner();
      if (runner && shutdownRunner(runner)) {
        logV("[mestro] left session");
        return;
      }
      logV("[mestro] leave: no runner");
    } catch (e) {
      console.log("[mestro] leave failed: " + e);
    }
  }

  function buildPublicStartArgs(): any {
    // empty SessionName + Shared/AutoHostOrClient = join random PUBLIC session
    const StartGameArgs = FusionRuntime.class("Fusion.StartGameArgs");
    const GameMode = FusionRuntime.class("Fusion.GameMode");

    let args: any = null;
    try {
      args = StartGameArgs.alloc();
      try { args.method(".ctor", 0).invoke(); } catch (_) {}
    } catch (e) {
      try { args = StartGameArgs.new(); } catch (e2) {
        console.log("[mestro] StartGameArgs alloc failed: " + e2);
        return null;
      }
    }

    let modeVal: any = null;
    const modeNames = ["Shared", "AutoHostOrClient", "Client", "Host"];
    for (let i = 0; i < modeNames.length; i++) {
      try {
        const f = GameMode.field(modeNames[i]);
        if (f) {
          modeVal = f.value;
          logV("[mestro] GameMode." + modeNames[i] + " = " + modeVal);
          break;
        }
      } catch (_) {}
    }
    if (modeVal === null) {
      modeVal = 1; // Shared fallback
      logV("[mestro] GameMode fallback Shared=1");
    }

    try { args.field("GameMode").value = modeVal; } catch (_) {
      try { args.method("set_GameMode").invoke(modeVal); } catch (_2) {}
    }
    try { args.field("SessionName").value = NULL; } catch (_) {}
    try { args.method("set_SessionName").invoke(NULL); } catch (_) {}
    try { args.field("IsVisible").value = true; } catch (_) {}
    try { args.field("IsOpen").value = true; } catch (_) {}
    try { args.field("EnableClientSessionCreation").value = true; } catch (_) {}

    return args;
  }

  function createFreshRunner(): any {
    try {
      const go = GameObject.new();
      try { go.method("set_name").invoke(Il2Cpp.string("mestro_runner")); } catch (_) {}
      const runner = addComponent(go, NetworkRunnerClass);
      if (runner && !runner.isNull()) {
        try { runner.method("set_ProvideInput").invoke(true); } catch (_) {}
        logV("[mestro] fresh NetworkRunner created");
        return runner;
      }
    } catch (e) {
      logV("[mestro] createFreshRunner: " + e);
    }
    try {
      const found = sceneInstances(NetworkRunnerClass);
      if (found.length > 0) return found[0];
    } catch (_) {}
    return null;
  }

  function startPublicOnRunner(runner: any): boolean {
    if (!runner || runner.isNull()) return false;
    const args = buildPublicStartArgs();
    if (!args) return false;
    try {
      const result = runner.method("StartGame", 1).invoke(args);
      logV("[mestro] StartGame(PUBLIC) → " + result);
      return true;
    } catch (e1) {
      console.log("[mestro] StartGame(1) failed: " + e1);
    }
    try {
      runner.method("StartGame").invoke(args);
      logV("[mestro] StartGame(PUBLIC) ok");
      return true;
    } catch (e2) {
      console.log("[mestro] StartGame failed: " + e2);
    }
    return false;
  }

  // ——— random lobby join (New Room) ———
  // Reuses the game's own NetworkRunner (never destroys it, that is what removed the arms),
  // waits for the old session to really stop, then starts a public session on it.
  let joinState: any = null;

  function runnerFlag(runner: any, getter: string): boolean | null {
    try { return !!runner.method(getter).invoke(); } catch (_) { return null; }
  }

  // forget cached player/hand refs so the menu re-finds the rig after a join or leave
  function resetPlayerCaches() {
    playerRefs = null;
    nextPlayerRetry = 0;
    cachedPlayerTargets = [];
    cachedPlayerTargetsAt = 0;
    if (reference) {
      try { Destroy(reference); } catch (_) {}
      reference = null;
    }
  }

  function beginPublicJoin() {
    resetPlayerCaches();
    const old = getRunner();
    if (old && runnerFlag(old, "get_IsRunning") !== false) shutdownRunner(old);
    joinState = { phase: "wait", at: Date.now(), tries: 0 };
    console.log("[mestro] joining random lobby...");
  }

  function tickJoin() {
    if (!joinState) return;
    const now = Date.now();
    const runner = getRunner();

    if (joinState.phase === "wait") {
      const stillRunning = runner ? runnerFlag(runner, "get_IsRunning") : false;
      if (stillRunning && now - joinState.at < 4000) return;
      const r = runner || createFreshRunner();
      if (r && startPublicOnRunner(r)) {
        joinState.phase = "connecting";
        joinState.at = now;
      } else {
        console.log("[mestro] join failed: no runner");
        joinState = null;
      }
      return;
    }

    if (joinState.phase === "connecting") {
      const inSession = runner ? runnerFlag(runner, "get_IsInSession") : false;
      const online = runner ? runnerFlag(runner, "get_IsConnectedToServer") : false;
      const joined = inSession === null ? online === true : inSession === true;
      if (joined) {
        console.log("[mestro] joined random lobby");
        resetPlayerCaches();
        joinState = null;
        return;
      }
      if (now - joinState.at > 20000) {
        joinState.tries++;
        console.log("[mestro] lobby join timed out (try " + joinState.tries + ")");
        if (joinState.tries >= 2) {
          console.log("[mestro] lobby join gave up - press New Room again");
          joinState = null;
          return;
        }
        if (runner) shutdownRunner(runner);
        joinState.phase = "wait";
        joinState.at = now;
      }
    }
  }

  // results of the last dump, shown on the in-game CAT_DUMP page
  let dumpLines: string[] = [];

  function buildDumpPage() {
    const list: any[] = [
      new ButtonInfo({ buttonText: "Back", keepOn: false, method: () => { currentCategory = CAT_HOME; currentPage = 0; } }),
      new ButtonInfo({ buttonText: "Run Dump", keepOn: false, method: () => dumpFxMethods() }),
      new ButtonInfo({ buttonText: "Found " + dumpLines.length + " methods (see Quest Tools)", keepOn: false, method: () => {} })
    ];
    for (let i = 0; i < dumpLines.length; i++) {
      const t = dumpLines[i];
      const shown = t.length > 70 ? t.substring(0, 70) : t;
      list.push(new ButtonInfo({ buttonText: (i + 1) + ". " + shown, keepOn: false, method: () => {} }));
    }
    buttons[CAT_DUMP] = list;
  }

  // lists gun/weapon classes and their networking-looking methods so the real replicated effect calls can be found
  function dumpFxMethods() {
    dumpLines = [];
    // classes that move/affect players, and methods that look like replicated calls on them
    const classRe = /(Gun|Weapon|Shoot|Laser|Projectile|Fire|Tool|Blaster|Item|Player|Rig|Locomotion|Hand|Net|Body|Ragdoll|Character|Fling|Event|Round|Season|Weather|Holiday|Game|Sound|Audio|Voice|Music|Play)/i;
    const methodRe = /(Rpc|RPC|Velocity|Force|Impulse|Knock|Fling|Launch|Push|Teleport|Move|Position|Fx|Effect|Laser|Shoot|Fire|Hit|Event|Start|Trigger|Weather|Sound|Audio|Play|Voice|Music|Round)/i;
    let classCount = 0;
    let methodCount = 0;
    console.log("[FX] scanning Assembly-CSharp for gun/effect methods...");
    try {
      for (const c of AssemblyCSharp.classes) {
        let name = "";
        try { name = c.name; } catch (_) { continue; }
        if (!classRe.test(name)) continue;
        classCount++;
        let parent = "";
        try { parent = c.parent ? c.parent.name : ""; } catch (_) {}
        try {
          for (const m of c.methods) {
            if (!methodRe.test(m.name)) continue;
            methodCount++;
            const line = name + " : " + parent + " ." + m.name + "(" + m.parameterCount + ")";
            console.log("[FX] " + line);
            dumpLines.push(line);
          }
        } catch (_) {}
      }
    } catch (e) {
      console.log("[FX] scan failed: " + e);
    }
    console.log("[FX] done: " + classCount + " classes, " + methodCount + " methods");
    console.log("[FX] results are listed above in Quest Tools; " + dumpLines.length + " lines");
    try { buildDumpPage(); } catch (e) { console.log("[FX] page failed: " + e); }
    currentCategory = CAT_DUMP;
    currentPage = 0;
  }

  function newRoomJoin() {
    try { beginPublicJoin(); } catch (e) { console.log("[mestro] new room failed: " + e); }
  }

  let flyspeed = 8.0; // lower default — high speed + physics = crash
  let la = false;
  let noclipOn = false;

  function setRBVelocity(rb: any, v: any) {
    if (!rb || rb.isNull()) return;
    try {
      rb.method("set_velocity", 1).invoke(v);
    } catch (e) {
      try {
        rb.method("set_linearVelocity", 1).invoke(v);
      } catch (e2) {}
    }
  }

  let flyOn = false;
  let flyWarned = false;
  let flyLogCount = 0;
  let flyLastLog = 0;
  let flyLastMove = 0;
  let flyHookCount = 0;
  let flyHookFired = 0;
  let flyTitleAt = 0;

  function flyNote(msg: string) {
    if (flyLogCount >= 8) return;
    flyLogCount++;
    logV("[Fly] " + msg);
  }

  function handAimDir(hand: any): any {
    // controller point direction — try several sources so it isn't stuck up/down only
    if (!hand || hand.isNull()) return Vector3.field("forwardVector").value;
    try {
      const fwd = hand.method("get_forward").invoke();
      const fx = fwd.field("x").value;
      const fy = fwd.field("y").value;
      const fz = fwd.field("z").value;
      // if nearly pure up/down, rebuild from rotation * forward
      if (Math.abs(fy) > 0.92 && Math.abs(fx) < 0.15 && Math.abs(fz) < 0.15) {
        try {
          const rot = hand.method("get_rotation").invoke();
          const worldFwd = Quaternion.method("op_Multiply", 2).invoke(rot, Vector3.field("forwardVector").value);
          return worldFwd;
        } catch (_) {}
      }
      return fwd;
    } catch (e) {
      try {
        const rot = hand.method("get_rotation").invoke();
        return Quaternion.method("op_Multiply", 2).invoke(rot, Vector3.field("forwardVector").value);
      } catch (e2) {
        return Vector3.field("forwardVector").value;
      }
    }
  }

  function movePlayerBy(dir: any, speed: number) {
    const p = resolvePlayer();
    if (!p || !p.obj || p.obj.isNull()) return false;
    try {
      const rawDt = Time.method("get_deltaTime").invoke();
      const dt = rawDt > 0.05 ? 0.05 : rawDt < 0 ? 0 : rawDt;
      const delta = Vector3.method("op_Multiply", 2).invoke(dir, speed * dt);
      const pos = p.obj.method("get_position").invoke();
      p.obj.method("set_position").invoke(Vector3.method("op_Addition", 2).invoke(pos, delta));
      // kill physics fight so movement sticks
      try {
        const rb = getComponent(p.obj, Rigidbody);
        if (rb && !rb.isNull()) {
          setRBVelocity(rb, Vector3.method("op_Multiply", 2).invoke(dir, speed));
        }
      } catch (_) {}
      return true;
    } catch (e) {
      return false;
    }
  }

  function Fly() {
    if (!flyOn) return;
    const p = resolvePlayer();
    if (!p || !p.obj || p.obj.isNull()) {
      if (!flyWarned) {
        flyWarned = true;
        logV("[Fly] no player root transform");
      }
      return;
    }

    // hold either trigger to fly as long as you want
    const trigHeld = rightTrigger || leftTrigger || rightTriggerAxis >= TRIGGER_HOLD || leftTriggerAxis >= TRIGGER_HOLD;
    const hand = handTransform(false) || handTransform(true);
    const now = Date.now();

    // fly logs disabled — spam was noise + minor lag

    if (!trigHeld) {
      try {
        const rb = getComponent(p.obj, Rigidbody);
        if (rb && !rb.isNull()) setRBVelocity(rb, Vector3.field("zeroVector").value);
      } catch (_) {}
      return;
    }
    if (!hand) return;

    // soft fly — velocity only (less likely to hard-crash physics)
    try {
      const dir = handAimDir(hand);
      const pull = Math.max(rightTriggerAxis, leftTriggerAxis, trigHeld ? 1 : 0);
      const speed = Math.min(flyspeed, 20) * (0.35 + 0.65 * Math.min(1, pull));
      const rb = getComponent(p.obj, Rigidbody);
      if (rb && !rb.isNull()) {
        setRBVelocity(rb, Vector3.method("op_Multiply", 2).invoke(dir, speed));
      } else {
        // fallback tiny position step
        movePlayerBy(dir, Math.min(speed, 10));
      }
    } catch (e) {}
  }

  function setFlyMovement(on: boolean) {
    flyOn = on;
    if (!on) {
      // clean unfly — kill residual velocity so you don't keep drifting
      try {
        const p = resolvePlayer();
        if (p && p.obj && !p.obj.isNull()) {
          const rb = getComponent(p.obj, Rigidbody);
          if (rb && !rb.isNull()) {
            setRBVelocity(rb, Vector3.field("zeroVector").value);
          }
        }
      } catch (e) {}
      flyHookFired = 0;
    }
    const p = resolvePlayer();
    const hasRoot = !!(p && p.obj && !p.obj.isNull());
    if (on) flyLogCount = 0;
    logV(
      "[Fly] " + (on ? "ON" : "OFF") +
      " root=" + (hasRoot ? "y" : "n") +
      " hooks=" + flyHookCount +
      " trig=" + (rightTrigger ? 1 : 0)
    );
  }

  // --- joystick fly ---
  let joystickFlyOn = false;
  let stickX = 0.0;
  let stickY = 0.0;

  function readAxis2D(controller: number): { x: number; y: number } {
    // try PrimaryThumbstick = 1 across controllers
    const tryIds = [1, 0];
    for (let i = 0; i < tryIds.length; i++) {
      try {
        const axis = OVRInputClass.method("Get", 2).invoke(tryIds[i], controller);
        if (!axis) continue;
        let x = 0, y = 0;
        try { x = axis.field("x").value; } catch (_) { try { x = axis.x; } catch (_2) {} }
        try { y = axis.field("y").value; } catch (_) { try { y = axis.y; } catch (_2) {} }
        x = Number(x) || 0;
        y = Number(y) || 0;
        if (Math.abs(x) > 0.01 || Math.abs(y) > 0.01) return { x: x, y: y };
      } catch (e) {}
    }
    return { x: 0, y: 0 };
  }

  function readThumbstick() {
    stickX = 0.0;
    stickY = 0.0;
    // Any / RTouch / LTouch — take strongest deflection
    const controllers = [0, 2, 1]; // Any, RTouch, LTouch (common OVR enums)
    let best = { x: 0, y: 0 };
    let bestMag = 0;
    for (let i = 0; i < controllers.length; i++) {
      const a = readAxis2D(controllers[i]);
      const m = Math.abs(a.x) + Math.abs(a.y);
      if (m > bestMag) {
        bestMag = m;
        best = a;
      }
    }
    stickX = best.x;
    stickY = best.y;
  }

  function JoystickFly() {
    if (!joystickFlyOn) return;
    const p = resolvePlayer();
    if (!p || !p.obj || p.obj.isNull()) return;

    readThumbstick();
    const mag = Math.sqrt(stickX * stickX + stickY * stickY);
    if (mag < 0.08) return;

    try {
      // head-forward fly is most reliable on Quest
      let basis = null;
      try {
        if (p.head && !p.head.isNull()) basis = p.head;
      } catch (_) {}
      if (!basis) {
        const hand = handTransform(false) || handTransform(true);
        if (hand) basis = hand;
      }
      if (!basis) basis = getTransform(p.obj);

      const fwd = handAimDir(basis);
      let fx = 0, fy = 0, fz = 0;
      try {
        fx = fwd.field("x").value;
        fy = fwd.field("y").value;
        fz = fwd.field("z").value;
      } catch (_) {
        return;
      }
      // right = cross(up, forward) approx horizontal
      let rx = -fz, rz = fx;
      const rlen = Math.sqrt(rx * rx + rz * rz) || 1;
      rx /= rlen; rz /= rlen;

      // stickY = forward/back along look, stickX = strafe
      const dx = fx * stickY + rx * stickX;
      const dy = fy * stickY;
      const dz = fz * stickY + rz * stickX;
      const dlen = Math.sqrt(dx * dx + dy * dy + dz * dz) || 1;
      const dir = v3(dx / dlen, dy / dlen, dz / dlen);
      const speed = Math.max(flyspeed, 10) * Math.min(1.2, mag);

      const rb = getComponent(p.obj, Rigidbody);
      if (rb && !rb.isNull()) {
        setRBVelocity(rb, Vector3.method("op_Multiply", 2).invoke(dir, speed));
      } else {
        movePlayerBy(dir, speed);
      }
    } catch (e) {
      console.log("[JoystickFly] err: " + e);
    }
  }

  function setJoystickFly(on: boolean) {
    joystickFlyOn = on;
    if (!on) {
      try {
        const p = resolvePlayer();
        if (p && p.obj && !p.obj.isNull()) {
          const rb = getComponent(p.obj, Rigidbody);
          if (rb && !rb.isNull()) setRBVelocity(rb, Vector3.field("zeroVector").value);
        }
      } catch (e) {}
    }
    logV("[JoystickFly] " + (on ? "ON — push stick to fly" : "OFF"));
  }

  // --- platforms ---
  let platformsOn = false;
  let platL = null;
  let platR = null;

  function destroyPlatforms() {
    if (platL != null) {
      try { Destroy(platL); } catch (e) {}
      platL = null;
    }
    if (platR != null) {
      try { Destroy(platR); } catch (e) {}
      platR = null;
    }
  }

  function ensureSolidPlatform(obj: any) {
    if (!obj || obj.isNull()) return;
    try {
      const col = getComponent(obj, BoxCollider);
      if (col && !col.isNull()) {
        col.method("set_enabled").invoke(true);
        col.method("set_isTrigger").invoke(false);
      }
      // solid unlit color so you can see the pad
      try {
        const r = getComponent(obj, Renderer);
        const mat = r.method("get_material").invoke();
        if (MenuShader && !MenuShader.isNull()) mat.method("set_shader").invoke(MenuShader);
        mat.method("set_color").invoke([0.15, 0.85, 0.35, 1.0]);
      } catch (_) {}
    } catch (e) {}
  }

  function placePlatform(ref: any, grab: boolean, held: any, offset: number[]) {
    // only while gripping — release deletes the pad
    if (!held || !grab) {
      if (ref != null) {
        try { Destroy(ref); } catch (e) {}
      }
      return null;
    }
    let target = held.method("get_position").invoke();
    try {
      // offset in hand local space so pad sits under palm
      const rot = held.method("get_rotation").invoke();
      const local = v3(offset[0], offset[1], offset[2]);
      const worldOff = Quaternion.method("op_Multiply", 2).invoke(rot, local);
      target = Vector3.method("op_Addition", 2).invoke(target, worldOff);
    } catch (e) {
      target = Vector3.method("op_Addition", 2).invoke(target, v3(offset[0], offset[1], offset[2]));
    }
    if (ref == null) {
      // thin wide pad — collider solid for standing
      ref = createObject(target, held.method("get_rotation").invoke(), [0.04, 0.35, 0.35], 3, [0.15, 0.85, 0.35, 1.0]);
      ensureSolidPlatform(ref);
      return ref;
    }
    try {
      const t = getTransform(ref);
      t.method("set_position").invoke(target);
      t.method("set_rotation").invoke(held.method("get_rotation").invoke());
      ensureSolidPlatform(ref);
    } catch (e) {}
    return ref;
  }

  function Platforms() {
    if (!platformsOn) {
      destroyPlatforms();
      return;
    }
    platL = placePlatform(platL, leftGrab, handTransform(true), [0.0, -0.06, 0.0]);
    platR = placePlatform(platR, rightGrab, handTransform(false), [0.0, -0.06, 0.0]);
  }

  function setPlatforms(on: boolean) {
    platformsOn = on;
    if (!on) destroyPlatforms();
    logV("[Platforms] " + (on ? "ON — hold GRIP under your hand to stand" : "OFF"));
  }

  function toggleColliders(enabled) {
    try {
      const colliders = Object.method("FindObjectsOfType", 0).inflate(Collider).invoke();
      for (let i = 0; i < colliders.length; i++) {
        colliders.get(i).method("set_enabled").invoke(enabled);
      }
    } catch (e) {
      logV("[Noclip] " + e);
    }
  }

  function setNoclip(on: boolean) {
    if (noclipOn === on) return;
    noclipOn = on;
    toggleColliders(!on);
    logV("[Noclip] " + (on ? "ON" : "OFF"));
  }

  // ——— Walk Speed (very fast) ———
  let walkSpeedOn = false;
  let walkSpeedValue = 28.0; // units/sec horizontal

  function WalkSpeedTick() {
    if (!walkSpeedOn) return;
    const p = resolvePlayer();
    if (!p || !p.obj || p.obj.isNull()) return;
    try {
      // 1) boost existing velocity if moving
      const rb = getComponent(p.obj, Rigidbody);
      let boosted = false;
      if (rb && !rb.isNull()) {
        let vx = 0, vy = 0, vz = 0;
        try {
          const vel = rb.method("get_velocity").invoke();
          vx = vel.field("x").value;
          vy = vel.field("y").value;
          vz = vel.field("z").value;
        } catch (_) {
          try {
            const vel = rb.method("get_linearVelocity").invoke();
            vx = vel.field("x").value;
            vy = vel.field("y").value;
            vz = vel.field("z").value;
          } catch (_2) {}
        }
        const hmag = Math.sqrt(vx * vx + vz * vz);
        if (hmag > 0.05) {
          const scale = walkSpeedValue / hmag;
          setRBVelocity(rb, v3(vx * scale, vy, vz * scale));
          boosted = true;
        }
      }
      // 2) if not moving via physics, drive from thumbstick + head look
      if (!boosted) {
        readThumbstick();
        const smag = Math.sqrt(stickX * stickX + stickY * stickY);
        if (smag < 0.1) return;
        let basis = null;
        try { if (p.head && !p.head.isNull()) basis = p.head; } catch (_) {}
        if (!basis) basis = getTransform(p.obj);
        const fwd = handAimDir(basis);
        let fx = 0, fz = 0;
        try {
          fx = fwd.field("x").value;
          fz = fwd.field("z").value;
        } catch (_) { return; }
        // flatten forward
        const fl = Math.sqrt(fx * fx + fz * fz) || 1;
        fx /= fl; fz /= fl;
        const rx = -fz, rz = fx;
        const dx = fx * stickY + rx * stickX;
        const dz = fz * stickY + rz * stickX;
        const dl = Math.sqrt(dx * dx + dz * dz) || 1;
        const dir = v3(dx / dl, 0, dz / dl);
        const speed = walkSpeedValue * Math.min(1.0, smag);
        if (rb && !rb.isNull()) {
          // keep current vertical vel
          let vy = 0;
          try {
            const vel = rb.method("get_velocity").invoke();
            vy = vel.field("y").value;
          } catch (_) {}
          setRBVelocity(rb, v3(dir.field ? dir.field("x").value * speed : dx / dl * speed, vy, dir.field ? dir.field("z").value * speed : dz / dl * speed));
          // safer explicit
          setRBVelocity(rb, v3((dx / dl) * speed, vy, (dz / dl) * speed));
        } else {
          movePlayerBy(v3(dx / dl, 0, dz / dl), speed);
        }
      }
    } catch (e) {}
  }

  function setWalkSpeed(on: boolean) {
    walkSpeedOn = on;
    logV("[WalkSpeed] " + (on ? "ON — move stick / walk to go fast (" + walkSpeedValue + ")" : "OFF"));
  }

  // ——— High Jump (very high) ———
  let highJumpOn = false;
  let jumpPower = 42.0;
  let lastJumpMs = 0;

  function HighJumpTick() {
    if (!highJumpOn) return;
    const p = resolvePlayer();
    if (!p || !p.obj || p.obj.isNull()) return;
    const now = Date.now();
    // primary button = jump boost (either hand)
    const jumpBtn = leftPrimary || rightPrimary;
    if (!jumpBtn) return;
    if (now - lastJumpMs < 250) return;
    lastJumpMs = now;
    try {
      const rb = getComponent(p.obj, Rigidbody);
      const up = Vector3.field("upVector").value;
      if (rb && !rb.isNull()) {
        setRBVelocity(rb, Vector3.method("op_Multiply", 2).invoke(up, jumpPower));
        try { rb.method("AddForce", 2).invoke(Vector3.method("op_Multiply", 2).invoke(up, jumpPower * 20), 1); } catch (_) {}
      }
      // hard pop up so it always feels insane
      hardMoveTarget(p.obj, up, 3.5);
      logV("[Jump] BOOST " + jumpPower);
    } catch (e) {}
  }

  function setHighJump(on: boolean) {
    highJumpOn = on;
    logV("[Jump] " + (on ? "ON very high — press A/X (primary)" : "OFF"));
  }

  // ===================== FUN MOVEMENT =====================
  let hoverOn = false;
  let dashOn = false;
  let grappleOn = false;
  let bunnyOn = false;
  let moonOn = false;
  let rocketJumpOn = false;
  let airStrafeOn = false;
  let lastDashMs = 0;
  let lastPrimaryEdge = false;
  let lastSecondaryEdge = false;
  let grapplePoint: any = null;
  let dashPower = 55.0;
  let grappleSpeed = 40.0;
  let moonGravityScale = 0.25;

  function getPlayerRb(): any {
    const p = resolvePlayer();
    if (!p || !p.obj || p.obj.isNull()) return null;
    try {
      const rb = getComponent(p.obj, Rigidbody);
      if (rb && !rb.isNull()) return rb;
    } catch (_) {}
    return null;
  }

  function HoverTick() {
    if (!hoverOn) return;
    const p = resolvePlayer();
    if (!p || !p.obj || p.obj.isNull()) return;
    // soft hover: kill downward velocity, gentle hold
    try {
      const rb = getPlayerRb();
      if (rb) {
        let vx = 0, vy = 0, vz = 0;
        try {
          const vel = rb.method("get_velocity").invoke();
          vx = vel.field("x").value; vy = vel.field("y").value; vz = vel.field("z").value;
        } catch (_) {
          try {
            const vel = rb.method("get_linearVelocity").invoke();
            vx = vel.field("x").value; vy = vel.field("y").value; vz = vel.field("z").value;
          } catch (_2) { return; }
        }
        if (vy < 0) vy = 0;
        // tiny upward float
        vy = Math.max(vy, 0.35);
        setRBVelocity(rb, v3(vx, vy, vz));
      }
    } catch (_) {}
  }

  function DashTick() {
    if (!dashOn) return;
    const now = Date.now();
    // dash on primary press edge (A/X) while dash enabled
    const primary = leftPrimary || rightPrimary;
    const edge = primary && !lastPrimaryEdge;
    lastPrimaryEdge = primary;
    if (!edge) return;
    if (now - lastDashMs < 350) return;
    lastDashMs = now;
    try {
      const hand = handTransform(false) || handTransform(true);
      const p = resolvePlayer();
      if (!p || !p.obj) return;
      const dir = hand ? handAimDir(hand) : Vector3.field("forwardVector").value;
      const rb = getPlayerRb();
      if (rb) {
        setRBVelocity(rb, Vector3.method("op_Multiply", 2).invoke(dir, dashPower));
      }
      movePlayerBy(dir, dashPower * 0.35);
      // extra pop
      hardMoveTarget(p.obj, dir, 2.2);
      logV("[Dash] BOOM " + dashPower);
    } catch (e) {
      console.log("[Dash] fail: " + e);
    }
  }

  function GrappleTick() {
    if (!grappleOn) return;
    // hold secondary (B/Y) = pull toward where you aim
    const sec = leftSecondary || rightSecondary;
    if (!sec) {
      grapplePoint = null;
      return;
    }
    try {
      const hand = handTransform(false) || handTransform(true);
      if (!hand) return;
      const origin = hand.method("get_position").invoke();
      const dir = handAimDir(hand);
      // lock point on first frame of hold
      if (!grapplePoint) {
        grapplePoint = Vector3.method("op_Addition", 2).invoke(
          origin,
          Vector3.method("op_Multiply", 2).invoke(dir, 16.0)
        );
        logV("[Grapple] locked");
      }
      const p = resolvePlayer();
      if (!p || !p.obj) return;
      const pos = p.obj.method("get_position").invoke();
      const to = Vector3.method("op_Subtraction", 2).invoke(grapplePoint, pos);
      let nd = to;
      try { nd = Vector3.method("Normalize", 1).invoke(to); } catch (_) {}
      const rb = getPlayerRb();
      if (rb) setRBVelocity(rb, Vector3.method("op_Multiply", 2).invoke(nd, grappleSpeed));
      movePlayerBy(nd, grappleSpeed * 0.5);
    } catch (e) {}
  }

  function BunnyTick() {
    if (!bunnyOn) return;
    // auto re-boost when falling near peak of jump (spam vertical)
    const rb = getPlayerRb();
    if (!rb) return;
    try {
      let vy = 0;
      try { vy = rb.method("get_velocity").invoke().field("y").value; } catch (_) {
        try { vy = rb.method("get_linearVelocity").invoke().field("y").value; } catch (_2) { return; }
      }
      // when almost landing / falling slow, bounce
      if (vy < -1.5 && vy > -8) {
        const up = Vector3.field("upVector").value;
        setRBVelocity(rb, Vector3.method("op_Multiply", 2).invoke(up, Math.max(jumpPower * 0.85, 30)));
      }
    } catch (_) {}
  }

  function MoonTick() {
    if (!moonOn) return;
    const rb = getPlayerRb();
    if (!rb) return;
    try {
      let vx = 0, vy = 0, vz = 0;
      try {
        const vel = rb.method("get_velocity").invoke();
        vx = vel.field("x").value; vy = vel.field("y").value; vz = vel.field("z").value;
      } catch (_) {
        try {
          const vel = rb.method("get_linearVelocity").invoke();
          vx = vel.field("x").value; vy = vel.field("y").value; vz = vel.field("z").value;
        } catch (_2) { return; }
      }
      // reduce downward pull
      if (vy < 0) vy *= moonGravityScale;
      setRBVelocity(rb, v3(vx, vy, vz));
    } catch (_) {}
  }

  function RocketJumpTick() {
    if (!rocketJumpOn) return;
    // grip = rocket blast up+back from hand aim
    if (!(leftGrab || rightGrab)) return;
    const now = Date.now();
    if (now - lastJumpMs < 400) return;
    lastJumpMs = now;
    try {
      const hand = handTransform(false) || handTransform(true);
      const p = resolvePlayer();
      if (!p || !p.obj) return;
      let dir = Vector3.field("upVector").value;
      if (hand) {
        // opposite of aim = blast away from where you point (classic rocket jump feel)
        const aim = handAimDir(hand);
        try {
          dir = Vector3.method("op_Multiply", 2).invoke(aim, -1.0);
        } catch (_) {}
        // mix up
        try {
          dir = Vector3.method("op_Addition", 2).invoke(
            dir,
            Vector3.method("op_Multiply", 2).invoke(Vector3.field("upVector").value, 1.2)
          );
          dir = Vector3.method("Normalize", 1).invoke(dir);
        } catch (_) {}
      }
      const rb = getPlayerRb();
      if (rb) setRBVelocity(rb, Vector3.method("op_Multiply", 2).invoke(dir, 48));
      hardMoveTarget(p.obj, dir, 2.5);
      logV("[RocketJump] blast");
    } catch (_) {}
  }

  function AirStrafeTick() {
    if (!airStrafeOn) return;
    // stick while airborne = strong lateral control
    readThumbstick();
    const mag = Math.sqrt(stickX * stickX + stickY * stickY);
    if (mag < 0.2) return;
    try {
      const hand = handTransform(false) || handTransform(true);
      const p = resolvePlayer();
      if (!p || !p.obj) return;
      const basis = hand || p.obj;
      const fwd = handAimDir(basis);
      let right = basis.method("get_right").invoke();
      const dir = Vector3.method("op_Addition", 2).invoke(
        Vector3.method("op_Multiply", 2).invoke(fwd, stickY),
        Vector3.method("op_Multiply", 2).invoke(right, stickX)
      );
      let nd = dir;
      try { nd = Vector3.method("Normalize", 1).invoke(dir); } catch (_) {}
      movePlayerBy(nd, 22 * mag);
      const rb = getPlayerRb();
      if (rb) {
        try {
          const vel = Vector3.method("op_Multiply", 2).invoke(nd, 22 * mag);
          // preserve some Y
          let vy = 0;
          try { vy = rb.method("get_velocity").invoke().field("y").value; } catch (_) {}
          setRBVelocity(rb, v3(
            vel.field ? vel.field("x").value : 0,
            vy,
            vel.field ? vel.field("z").value : 0
          ));
        } catch (_) {
          setRBVelocity(rb, Vector3.method("op_Multiply", 2).invoke(nd, 20 * mag));
        }
      }
    } catch (_) {}
  }

  function applyMovementPreset(name: string) {
    if (name === "normal") {
      walkSpeedValue = 12;
      jumpPower = 22;
      flyspeed = 12;
      dashPower = 30;
      logV("[Preset] Normal");
    } else if (name === "fast") {
      walkSpeedValue = 28;
      jumpPower = 42;
      flyspeed = 22;
      dashPower = 55;
      setWalkSpeed(true);
      setHighJump(true);
      logV("[Preset] Fast");
    } else if (name === "insane") {
      walkSpeedValue = 55;
      jumpPower = 85;
      flyspeed = 40;
      dashPower = 80;
      grappleSpeed = 55;
      setWalkSpeed(true);
      setHighJump(true);
      setFlyMovement(true);
      hoverOn = true;
      dashOn = true;
      bunnyOn = true;
      airStrafeOn = true;
      logV("[Preset] INSANE — walk/jump/fly/hover/dash/bunny/strafe ON");
    } else if (name === "spider") {
      // grapple + hover + moon = web-swing vibes
      grappleOn = true;
      hoverOn = true;
      moonOn = true;
      airStrafeOn = true;
      logV("[Preset] Spider — grapple+hover+moon+strafe");
    }
  }

  function FunMovementTick() {
    // skip all work if nothing enabled (big FPS win)
    if (!hoverOn && !dashOn && !grappleOn && !bunnyOn && !moonOn && !rocketJumpOn && !airStrafeOn) return;
    if (hoverOn) { try { HoverTick(); } catch (_) {} }
    if (dashOn) { try { DashTick(); } catch (_) {} }
    if (grappleOn) { try { GrappleTick(); } catch (_) {} }
    if (bunnyOn) { try { BunnyTick(); } catch (_) {} }
    if (moonOn) { try { MoonTick(); } catch (_) {} }
    if (rocketJumpOn) { try { RocketJumpTick(); } catch (_) {} }
    if (airStrafeOn) { try { AirStrafeTick(); } catch (_) {} }
  }

  // ——— Panic: kill everything ———
  function panicDisableAll() {
    try { setFlyMovement(false); } catch (_) {}
    try { setJoystickFly(false); } catch (_) {}
    try { setPlatforms(false); } catch (_) {}
    try { setNoclip(false); } catch (_) {}
    try { setWalkSpeed(false); } catch (_) {}
    try { setHighJump(false); } catch (_) {}
    hoverOn = false;
    dashOn = false;
    grappleOn = false;
    bunnyOn = false;
    moonOn = false;
    rocketJumpOn = false;
    airStrafeOn = false;
    grapplePoint = null;
    try { setForcePickup(false); } catch (_) {}
    try { setGhost(false); } catch (_) {}
    try { setGun(""); } catch (_) {}
    try { destroyLaser(); } catch (_) {}
    try { gunFxQueue = []; } catch (_) {}
    try { stopSoundboard(); } catch (_) {}
    // reset long arms if on
    try { if (la) toggleLongArms(); } catch (_) {}
    // turn off all keepOn buttons
    try {
      for (let i = 0; i < buttons.length; i++) {
        for (let j = 0; j < buttons[i].length; j++) {
          const b = buttons[i][j];
          if (b && b.keepOn && b.enabled) {
            b.enabled = false;
            try { if (b.disableMethod) b.disableMethod(); } catch (_) {}
          }
        }
      }
    } catch (_) {}
    logV("[PANIC] all cheats OFF");
  }

  // ——— Teleport helpers ———
  function teleportSelfToPoint(pos: any) {
    const p = resolvePlayer();
    if (!p || !p.obj || p.obj.isNull()) return;
    try {
      p.obj.method("set_position").invoke(pos);
      try {
        const rb = getComponent(p.obj, Rigidbody);
        if (rb && !rb.isNull()) setRBVelocity(rb, Vector3.field("zeroVector").value);
      } catch (_) {}
      logV("[TP] self moved");
    } catch (e) {
      console.log("[TP] self failed: " + e);
    }
  }

  function laserEndPoint(dist: number): any {
    const hand = handTransform(false) || handTransform(true);
    if (!hand) return null;
    const origin = hand.method("get_position").invoke();
    const dir = handAimDir(hand);
    return Vector3.method("op_Addition", 2).invoke(
      origin,
      Vector3.method("op_Multiply", 2).invoke(dir, dist)
    );
  }

  function teleportGunFire() {
    const pt = laserEndPoint(18.0);
    if (!pt) {
      logV("[TP Gun] no hand");
      return;
    }
    teleportSelfToPoint(pt);
  }

  function teleportEveryoneToLaser() {
    const pt = laserEndPoint(12.0);
    if (!pt) return;
    const local = getLocalRoot();
    let localPos: any = null;
    try { if (local) localPos = local.method("get_position").invoke(); } catch (_) {}
    const all = getAllPlayerTargets();
    let n = 0;
    for (let i = 0; i < all.length; i++) {
      try {
        if (localPos && isProbablySelf(all[i], localPos)) continue;
        tryRequestAuthority(all[i]);
        hardMoveTarget(all[i], Vector3.field("zeroVector").value, 0);
        // set position absolute
        const t = getTransform(all[i]);
        t.method("set_position").invoke(pt);
        applyVelocityBurst(all[i], Vector3.field("upVector").value, 2);
        n++;
      } catch (_) {}
    }
    logV("[TP All] moved " + n + " players to laser point");
  }

  function teleportEveryoneToMe() {
    const local = getLocalRoot();
    if (!local) return;
    let myPos: any = null;
    try { myPos = local.method("get_position").invoke(); } catch (_) { return; }
    const all = getAllPlayerTargets();
    let n = 0;
    for (let i = 0; i < all.length; i++) {
      try {
        if (isProbablySelf(all[i], myPos)) continue;
        tryRequestAuthority(all[i]);
        const t = getTransform(all[i]);
        // offset so they don't stack inside you
        const offset = v3((i % 3) * 0.8 - 0.8, 0.2, Math.floor(i / 3) * 0.8);
        const dest = Vector3.method("op_Addition", 2).invoke(myPos, offset);
        t.method("set_position").invoke(dest);
        n++;
      } catch (_) {}
    }
    logV("[TP All] pulled " + n + " players to you");
  }

  function teleportToPlayer(target: any) {
    if (!target) return;
    const pos = targetWorldPos(target);
    if (!pos) return;
    // stand slightly beside them
    try {
      const dest = Vector3.method("op_Addition", 2).invoke(pos, v3(0.5, 0.1, 0.5));
      teleportSelfToPoint(dest);
    } catch (_) {
      teleportSelfToPoint(pos);
    }
  }

  function rebuildPlayerList() {
    const local = getLocalRoot();
    let localPos: any = null;
    try { if (local) localPos = local.method("get_position").invoke(); } catch (_) {}
    const all = getAllPlayerTargets();
    const list: any[] = [
      new ButtonInfo({
        buttonText: "Refresh List",
        keepOn: false,
        method: () => {
          rebuildPlayerList();
          currentCategory = CAT_PLAYERS;
          currentPage = 0;
          pendingMenuRebuild = true;
        }
      }),
      new ButtonInfo({
        buttonText: "TP Everyone To Me",
        keepOn: false,
        method: () => teleportEveryoneToMe()
      })
    ];
    let idx = 0;
    for (let i = 0; i < all.length; i++) {
      try {
        if (localPos && isProbablySelf(all[i], localPos)) continue;
        const pos = targetWorldPos(all[i]);
        let dist = 0;
        try {
          if (localPos && pos) dist = Vector3.method("Distance", 2).invoke(localPos, pos);
        } catch (_) {}
        const label = "TP P" + (idx + 1) + " (" + dist.toFixed(1) + "m)";
        const tgt = all[i];
        list.push(
          new ButtonInfo({
            buttonText: label,
            keepOn: false,
            reload: false,
            method: () => teleportToPlayer(tgt)
          })
        );
        idx++;
      } catch (_) {}
    }
    if (idx === 0) {
      list.push(
        new ButtonInfo({
          buttonText: "(no other players)",
          keepOn: false,
          method: () => logV("[Players] none found")
        })
      );
    }
    buttons[CAT_PLAYERS] = list;
    logV("[Players] listed " + idx);
  }

  function openPlayers() {
    rebuildPlayerList();
    currentCategory = CAT_PLAYERS;
    currentPage = 0;
  }

  function toggleLongArms() {
    const p = resolvePlayer();
    if (!p) return;
    la = !la;
    try {
      getTransform(p.obj).method("set_localScale").invoke(la ? [1.5, 1.5, 1.5] : [1.0, 1.0, 1.0]);
    } catch (e) {}
  }

  function BigHead() {
    const p = resolvePlayer();
    if (!p || !p.head || p.head.isNull()) return;
    try {
      getTransform(p.head).method("set_localScale").invoke([2.0, 2.0, 2.0]);
    } catch (e) {}
  }

  function ResetHead() {
    const p = resolvePlayer();
    if (!p || !p.head || p.head.isNull()) return;
    try {
      getTransform(p.head).method("set_localScale").invoke([1.0, 1.0, 1.0]);
    } catch (e) {}
  }

  function HeadSize(s: number) {
    const p = resolvePlayer();
    if (!p || !p.head || p.head.isNull()) return;
    try {
      getTransform(p.head).method("set_localScale").invoke([s, s, s]);
    } catch (e) {}
  }

  // ===================== OVERPOWERED =====================
  let forcePickupOn = false;
  let activeGun: string = ""; // "fly" | "kick" | "crash" | "black" | "fling" | "lockedmenu" | ""
  let gunCooldown = 0;
  let lockedMenuObjects: any[] = [];

  function getLocalRoot(): any {
    const p = resolvePlayer();
    return p && p.obj && !p.obj.isNull() ? p.obj : null;
  }

  function targetWorldPos(obj: any): any {
    try {
      const t = getTransform(obj);
      if (t && !t.isNull()) return t.method("get_position").invoke();
    } catch (_) {}
    return null;
  }

  function isProbablySelf(obj: any, localPos: any): boolean {
    try {
      const pos = targetWorldPos(obj);
      if (!pos || !localPos) return false;
      const d = Vector3.method("Distance", 2).invoke(localPos, pos);
      return d < 1.2;
    } catch (_) {
      return false;
    }
  }

  let cachedPlayerTargets: any[] = [];
  let cachedPlayerTargetsAt = 0;

  function getAllPlayerTargets(): any[] {
    const now = Date.now();
    // cache 400ms — FindObjectsOfType every shot was melting FPS
    if (cachedPlayerTargets.length > 0 && now - cachedPlayerTargetsAt < 400) {
      return cachedPlayerTargets;
    }
    const out: any[] = [];
    const seen = new Set<string>();
    function add(o: any) {
      if (!o || o.isNull()) return;
      try {
        const id = String(o.handle || o);
        if (seen.has(id)) return;
        seen.add(id);
        out.push(o);
      } catch (_) {
        out.push(o);
      }
    }
    try {
      const rigs = toJsArray(Object.method("FindObjectsOfType", 0).inflate(HardwareRigClass).invoke());
      for (let i = 0; i < rigs.length; i++) add(rigs[i]);
    } catch (_) {}
    try {
      if (LocomotionClass) {
        const locos = toJsArray(Object.method("FindObjectsOfType", 0).inflate(LocomotionClass).invoke());
        for (let i = 0; i < locos.length; i++) add(locos[i]);
      }
    } catch (_) {}
    // NetworkObject scan is heavy — only if we found almost nobody
    if (out.length < 2) {
      try {
        const nos = toJsArray(Object.method("FindObjectsOfType", 0).inflate(NetworkObjectClass).invoke());
        for (let i = 0; i < nos.length; i++) {
          try {
            const go = nos[i].method("get_gameObject").invoke();
            const name = String(go.method("get_name").invoke()).toLowerCase();
            if (name.indexOf("player") >= 0 || name.indexOf("rig") >= 0 || name.indexOf("avatar") >= 0) {
              add(nos[i]);
            }
          } catch (_) {}
        }
      } catch (_) {}
    }
    cachedPlayerTargets = out;
    cachedPlayerTargetsAt = now;
    return out;
  }

  // multi-frame gun effects — Fusion only replicates if we get StateAuthority
  let gunFxQueue: { kind: string; target: any; dir: any; power: number; framesLeft: number; dest?: any }[] = [];
  let lastGunNetNote = 0;

  function queueGunFx(kind: string, target: any, dir: any, power: number, frames: number, dest?: any) {
    gunFxQueue.push({ kind, target, dir, power, framesLeft: frames, dest: dest || null });
  }

  function isRunnerMaster(): boolean {
    try {
      const runner = getRunner();
      if (!runner) return false;
      try { if (runner.method("get_IsSharedModeMasterClient").invoke()) return true; } catch (_) {}
      try { if (runner.method("get_IsServer").invoke()) return true; } catch (_) {}
      try { if (runner.method("IsServer").invoke()) return true; } catch (_) {}
      try { if (runner.method("get_IsMasterClient").invoke()) return true; } catch (_) {}
      return false;
    } catch (_) {
      return false;
    }
  }

  function getGameObject(obj: any): any {
    try {
      if (!obj || obj.isNull()) return null;
      try { return obj.method("get_gameObject").invoke(); } catch (_) {}
      try { return getTransform(obj).method("get_gameObject").invoke(); } catch (_) {}
    } catch (_) {}
    return null;
  }

  function collectNetworkObjects(root: any): any[] {
    const list: any[] = [];
    const go = getGameObject(root);
    if (!go) {
      try {
        const no = getComponent(root, NetworkObjectClass);
        if (no && !no.isNull()) list.push(no);
      } catch (_) {}
      return list;
    }
    try {
      const arr = go.method("GetComponentsInChildren", 1).inflate(NetworkObjectClass).invoke(true);
      const js = toJsArray(arr);
      for (let i = 0; i < js.length; i++) if (js[i] && !js[i].isNull()) list.push(js[i]);
    } catch (_) {
      try {
        const no = getComponent(go, NetworkObjectClass);
        if (no && !no.isNull()) list.push(no);
      } catch (_2) {}
    }
    return list;
  }

  function networkHasAuthority(no: any): boolean {
    if (!no || no.isNull()) return false;
    try { if (no.method("get_HasStateAuthority").invoke()) return true; } catch (_) {}
    try { if (no.field("StateAuthority").value) { /* has some authority ref */ } } catch (_) {}
    try { if (no.method("get_HasInputAuthority").invoke()) return true; } catch (_) {}
    return false;
  }

  function tryRequestAuthority(obj: any): boolean {
    let got = false;
    const nos = collectNetworkObjects(obj);
    // also walk parents
    try {
      let t = getTransform(obj);
      for (let depth = 0; depth < 6 && t && !t.isNull(); depth++) {
        try {
          const go = t.method("get_gameObject").invoke();
          const no = getComponent(go, NetworkObjectClass);
          if (no && !no.isNull()) nos.push(no);
        } catch (_) {}
        try { t = t.method("get_parent").invoke(); } catch (_) { break; }
      }
    } catch (_) {}

    for (let i = 0; i < nos.length; i++) {
      const no = nos[i];
      try { no.method("RequestStateAuthority").invoke(); } catch (_) {}
      try { no.method("RequestStateAuthority", 0).invoke(); } catch (_) {}
      // host/server sometimes can assign
      try {
        const runner = getRunner();
        if (runner) {
          try { no.method("RequestStateAuthority").invoke(); } catch (_2) {}
        }
      } catch (_) {}
      if (networkHasAuthority(no)) got = true;
    }
    return got || isRunnerMaster();
  }

  function collectRigidbodies(root: any): any[] {
    const list: any[] = [];
    try {
      const rb = getComponent(root, Rigidbody);
      if (rb && !rb.isNull()) list.push(rb);
    } catch (_) {}
    try {
      const go = getGameObject(root);
      if (!go) return list;
      const arr = go.method("GetComponentsInChildren", 1).inflate(Rigidbody).invoke(true);
      const js = toJsArray(arr);
      for (let i = 0; i < js.length; i++) if (js[i] && !js[i].isNull()) list.push(js[i]);
    } catch (_) {}
    return list;
  }

  function setWorldPos(obj: any, pos: any) {
    try {
      const t = getTransform(obj);
      if (t && !t.isNull()) t.method("set_position").invoke(pos);
    } catch (_) {}
    try {
      const go = getGameObject(obj);
      if (go) getTransform(go).method("set_position").invoke(pos);
    } catch (_) {}
  }

  function hardMoveTarget(target: any, dir: any, distance: number) {
    try {
      const t = getTransform(target);
      if (!t || t.isNull()) return;
      const pos = t.method("get_position").invoke();
      const next = Vector3.method("op_Addition", 2).invoke(
        pos,
        Vector3.method("op_Multiply", 2).invoke(dir, distance)
      );
      setWorldPos(target, next);
      // slam every child NetworkObject root too
      const nos = collectNetworkObjects(target);
      for (let i = 0; i < nos.length; i++) {
        try { setWorldPos(nos[i], next); } catch (_) {}
      }
    } catch (_) {}
  }

  function hardSetTargetPos(target: any, pos: any) {
    setWorldPos(target, pos);
    const nos = collectNetworkObjects(target);
    for (let i = 0; i < nos.length; i++) {
      try { setWorldPos(nos[i], pos); } catch (_) {}
    }
    // locomotion roots often sit under hardware rig
    try {
      const go = getGameObject(target);
      if (go && LocomotionClass) {
        const locos = go.method("GetComponentsInChildren", 1).inflate(LocomotionClass).invoke(true);
        const js = toJsArray(locos);
        for (let i = 0; i < js.length; i++) {
          try { setWorldPos(js[i], pos); } catch (_) {}
        }
      }
    } catch (_) {}
  }

  // probe for game RPCs that might move players (names vary by build)
  function tryInvokeMoveRpcs(target: any, worldPos: any, vel: any) {
    let called = 0;
    const go = getGameObject(target);
    if (!go) return 0;
    const names = [
      "RPC_Teleport", "RpcTeleport", "Teleport", "TeleportTo",
      "RPC_Knockback", "RpcKnockback", "Knockback", "AddKnockback",
      "RPC_Impulse", "RpcImpulse", "ApplyImpulse", "AddImpulse",
      "RPC_Force", "ApplyForce", "SetPosition", "CmdMove"
    ];
    try {
      // NetworkBehaviour components
      let behaviours: any[] = [];
      try {
        const NetworkBehaviour = FusionRuntime.class("Fusion.NetworkBehaviour");
        const arr = go.method("GetComponentsInChildren", 1).inflate(NetworkBehaviour).invoke(true);
        behaviours = toJsArray(arr);
      } catch (_) {
        try {
          const arr = go.method("GetComponentsInChildren", 1).inflate(
            Il2Cpp.domain.assembly("Fusion.Runtime").image.class("Fusion.SimulationBehaviour")
          ).invoke(true);
          behaviours = toJsArray(arr);
        } catch (_2) {}
      }
      for (let b = 0; b < behaviours.length; b++) {
        const comp = behaviours[b];
        if (!comp || comp.isNull()) continue;
        for (let n = 0; n < names.length; n++) {
          try {
            comp.method(names[n], 1).invoke(worldPos);
            called++;
          } catch (_) {
            try {
              comp.method(names[n], 1).invoke(vel);
              called++;
            } catch (_2) {
              try {
                comp.method(names[n], 0).invoke();
                called++;
              } catch (_3) {}
            }
          }
        }
      }
    } catch (_) {}
    return called;
  }

  function applyVelocityBurst(target: any, dir: any, power: number): number {
    const auth = tryRequestAuthority(target);
    const vel = Vector3.method("op_Multiply", 2).invoke(dir, power);
    const rbs = collectRigidbodies(target);
    let n = 0;
    for (let i = 0; i < rbs.length; i++) {
      try {
        try { rbs[i].method("set_isKinematic").invoke(false); } catch (_) {}
        setRBVelocity(rbs[i], vel);
        try { rbs[i].method("AddForce", 2).invoke(vel, 1); } catch (_) {}
        try { rbs[i].method("AddForce", 2).invoke(vel, 2); } catch (_) {} // VelocityChange
        n++;
      } catch (_) {}
    }
    const step = Math.min(12, Math.max(2, power * 0.2));
    hardMoveTarget(target, dir, step);
    try {
      const t = getTransform(target);
      const pos = t.method("get_position").invoke();
      tryInvokeMoveRpcs(target, pos, vel);
    } catch (_) {}

    const now = Date.now();
    if (now - lastGunNetNote > 800) {
      lastGunNetNote = now;
      if (auth) {
        logV("[OP] authority path active — move may replicate");
      } else {
        logV("[OP] NO authority — Fusion keeps it LOCAL (others won't see fling)");
        logV("[OP] tip: host/master client has better luck; player objects block authority steal");
      }
    }
    return n;
  }

  function processGunFxQueue() {
    if (gunFxQueue.length === 0) return;
    const next: typeof gunFxQueue = [];
    for (let i = 0; i < gunFxQueue.length; i++) {
      const fx = gunFxQueue[i];
      if (!fx.target || fx.target.isNull()) continue;
      try {
        tryRequestAuthority(fx.target);
        if (fx.kind === "fling" || fx.kind === "pull" || fx.kind === "fly" || fx.kind === "kick") {
          applyVelocityBurst(fx.target, fx.dir, fx.power);
        }
        if (fx.dest) {
          hardSetTargetPos(fx.target, fx.dest);
        }
      } catch (_) {}
      fx.framesLeft--;
      if (fx.framesLeft > 0) next.push(fx);
    }
    gunFxQueue = next;
  }

  function nearestOtherPlayer(maxDist: number): any {
    const local = getLocalRoot();
    let localPos: any = null;
    try {
      if (local) localPos = local.method("get_position").invoke();
      else {
        const h = handTransform(false);
        if (h) localPos = h.method("get_position").invoke();
      }
    } catch (_) { return null; }
    if (!localPos) return null;

    const rigs = getAllPlayerTargets();
    let best: any = null;
    let bestD = maxDist;
    for (let i = 0; i < rigs.length; i++) {
      try {
        if (isProbablySelf(rigs[i], localPos)) continue;
        const pos = targetWorldPos(rigs[i]);
        if (!pos) continue;
        const d = Vector3.method("Distance", 2).invoke(localPos, pos);
        if (d < bestD) {
          bestD = d;
          best = rigs[i];
        }
      } catch (_) {}
    }
    return best;
  }

  function aimPlayer(maxDist: number): any {
    const hand = handTransform(false) || handTransform(true);
    const rigs = getAllPlayerTargets();
    let localPos: any = null;
    try {
      const local = getLocalRoot();
      if (local) localPos = local.method("get_position").invoke();
      else if (hand) localPos = hand.method("get_position").invoke();
    } catch (_) {}

    if (hand) {
      try {
        const origin = hand.method("get_position").invoke();
        const dir = handAimDir(hand);
        let best: any = null;
        let bestScore = 0.35; // loose aim cone so laser hits easier
        for (let i = 0; i < rigs.length; i++) {
          try {
            if (localPos && isProbablySelf(rigs[i], localPos)) continue;
            const pos = targetWorldPos(rigs[i]);
            if (!pos) continue;
            const to = Vector3.method("op_Subtraction", 2).invoke(pos, origin);
            const dist = Vector3.method("Magnitude", 1).invoke(to);
            if (dist < 0.8 || dist > maxDist) continue;
            const nd = Vector3.method("Normalize", 1).invoke(to);
            const dot = Vector3.method("Dot", 2).invoke(dir, nd);
            // score by aim quality + closeness
            const score = dot - dist * 0.01;
            if (dot > bestScore && score > (best ? bestScore : -999)) {
              bestScore = dot;
              best = rigs[i];
            }
          } catch (_) {}
        }
        if (best) return best;
      } catch (_) {}
    }
    return nearestOtherPlayer(maxDist);
  }

  function aimDirFromHand(): any {
    const hand = handTransform(false) || handTransform(true);
    if (hand) return handAimDir(hand);
    return Vector3.field("upVector").value;
  }

  function flingTarget(target: any, power: number) {
    if (!target) return;
    try {
      const dir = aimDirFromHand();
      const n = applyVelocityBurst(target, dir, power * 1.4);
      // long multi-frame slam — if we ever get authority, this sticks
      queueGunFx("fling", target, dir, power * 1.4, 45);
      // also queue absolute destinations along the fling path
      try {
        const t = getTransform(target);
        const pos = t.method("get_position").invoke();
        const far = Vector3.method("op_Addition", 2).invoke(
          pos,
          Vector3.method("op_Multiply", 2).invoke(dir, Math.min(25, power * 0.5))
        );
        queueGunFx("fling", target, dir, power, 30, far);
      } catch (_) {}
      logV("[OP] fling x" + power + " rbs=" + n + " master=" + (isRunnerMaster() ? "y" : "n"));
    } catch (e) {
      console.log("[OP] fling failed: " + e);
    }
  }

  function kickTarget(target: any) {
    if (!target) return;
    try {
      const dir = aimDirFromHand();
      applyVelocityBurst(target, dir, 90);
      queueGunFx("kick", target, dir, 90, 20);
      // yeet upward too
      try {
        hardMoveTarget(target, Vector3.field("upVector").value, 5.0);
      } catch (_) {}
      logV("[OP] kick applied");
    } catch (e) {
      console.log("[OP] kick failed: " + e);
    }
  }

  function crashTarget(target: any) {
    if (!target) return;
    try {
      // spam scale / destroy children / null-ish ops that often desync or hard-crash weak clients
      const t = getTransform(target);
      for (let i = 0; i < 12; i++) {
        try {
          t.method("set_localScale").invoke([999, 999, 999]);
          t.method("set_localScale").invoke([0.01, 0.01, 0.01]);
        } catch (e) {}
      }
      try { Destroy(target); } catch (e) {}
      logV("[OP] crash pulse sent");
    } catch (e) {
      console.log("[OP] crash failed: " + e);
    }
  }

  function blackScreenTarget(target: any) {
    if (!target) return;
    try {
      // local approximation: create a huge black quad parented in front of their head if possible
      const t = getTransform(target);
      const pos = t.method("get_position").invoke();
      const fwd = t.method("get_forward").invoke();
      const place = Vector3.method("op_Addition", 2).invoke(pos, Vector3.method("op_Multiply", 2).invoke(fwd, 0.35));
      const wall = createObject(place, t.method("get_rotation").invoke(), [0.05, 4.0, 4.0], 3, [0, 0, 0, 1]);
      lockedMenuObjects.push(wall);
      logV("[OP] black wall spawned on target");
    } catch (e) {
      console.log("[OP] black screen failed: " + e);
    }
  }

  function flyGunTarget(target: any) {
    if (!target) return;
    try {
      const up = Vector3.field("upVector").value;
      applyVelocityBurst(target, up, 25);
      queueGunFx("fly", target, up, 20, 25);
      hardMoveTarget(target, up, 6.0);
      logV("[OP] fly gun launched target");
    } catch (e) {
      console.log("[OP] fly gun failed: " + e);
    }
  }

  // Give locked mod menu — creates a visible non-interactive panel in front of the target
  // that says locked / mestro_ac. They see it, they can't use it.
  function giveLockedMenu(target: any) {
    if (!target) return;
    try {
      const t = getTransform(target);
      const pos = t.method("get_position").invoke();
      const fwd = t.method("get_forward").invoke();
      const place = Vector3.method("op_Addition", 2).invoke(
        pos,
        Vector3.method("op_Addition", 2).invoke(
          Vector3.method("op_Multiply", 2).invoke(fwd, 0.9),
          Vector3.method("op_Multiply", 2).invoke(Vector3.field("upVector").value, 0.4)
        )
      );

      // panel body
      const panel = createObject(place, t.method("get_rotation").invoke(), [0.08, 0.55, 0.7], 3, [0.08, 0.02, 0.14, 0.97]);
      // title bar
      const title = createObject(
        Vector3.method("op_Addition", 2).invoke(place, Vector3.method("op_Multiply", 2).invoke(Vector3.field("upVector").value, 0.32)),
        t.method("get_rotation").invoke(),
        [0.09, 0.55, 0.1],
        3,
        [0.55, 0.15, 0.75, 1.0]
      );

      // fake buttons that do nothing (no trigger handlers attached for victim)
      for (let i = 0; i < 5; i++) {
        const y = 0.18 - i * 0.1;
        const btnPos = Vector3.method("op_Addition", 2).invoke(
          place,
          Vector3.method("op_Multiply", 2).invoke(Vector3.field("upVector").value, y)
        );
        createObject(btnPos, t.method("get_rotation").invoke(), [0.07, 0.48, 0.07], 3, [0.18, 0.05, 0.28, 1.0]);
      }

      lockedMenuObjects.push(panel);
      lockedMenuObjects.push(title);
      logV("[OP] locked menu given — visible, non-functional");
    } catch (e) {
      console.log("[OP] locked menu failed: " + e);
    }
  }

  function pullTarget(target: any, power: number) {
    if (!target) return;
    try {
      const local = getLocalRoot();
      const hand = handTransform(false);
      let myPos: any = null;
      if (local) myPos = local.method("get_position").invoke();
      else if (hand) myPos = hand.method("get_position").invoke();
      if (!myPos) return;
      const theirPos = targetWorldPos(target);
      if (!theirPos) return;
      const toMe = Vector3.method("op_Subtraction", 2).invoke(myPos, theirPos);
      const dir = Vector3.method("Normalize", 1).invoke(toMe);
      applyVelocityBurst(target, dir, power);
      queueGunFx("pull", target, dir, power, 18);
      logV("[OP] pull applied");
    } catch (e) {
      console.log("[OP] pull failed: " + e);
    }
  }

  function sizeTarget(target: any, scale: number) {
    if (!target) return;
    try {
      tryRequestAuthority(target);
      getTransform(target).method("set_localScale").invoke([scale, scale, scale]);
      try {
        const go = target.method("get_gameObject").invoke();
        getTransform(go).method("set_localScale").invoke([scale, scale, scale]);
      } catch (_) {}
      // children rigidbodies scale root
      logV("[OP] size set " + scale);
    } catch (e) {
      console.log("[OP] size failed: " + e);
    }
  }

  function spamFxTarget(target: any) {
    if (!target) return;
    try {
      const t = getTransform(target);
      const pos = t.method("get_position").invoke();
      // spam primitive bursts around them — visual + physics noise
      for (let i = 0; i < 10; i++) {
        const ox = (Math.random() - 0.5) * 1.5;
        const oy = Math.random() * 1.5;
        const oz = (Math.random() - 0.5) * 1.5;
        const offset = Vector3.method("op_Addition", 2).invoke(
          pos,
          Vector3.method("op_Multiply", 2).invoke(
            Vector3.method("op_Addition", 2).invoke(
              Vector3.method("op_Multiply", 2).invoke(Vector3.field("rightVector").value, ox),
              Vector3.method("op_Addition", 2).invoke(
                Vector3.method("op_Multiply", 2).invoke(Vector3.field("upVector").value, oy),
                Vector3.method("op_Multiply", 2).invoke(Vector3.field("forwardVector").value, oz)
              )
            ),
            1.0
          )
        );
        const ball = createObject(offset, identityQuaternion, [0.15, 0.15, 0.15], 0, [
          Math.random(), Math.random(), Math.random(), 1.0
        ]);
        lockedMenuObjects.push(ball);
        try {
          const rb = addComponent(ball, Rigidbody);
          if (rb && !rb.isNull()) {
            setRBVelocity(rb, Vector3.method("op_Multiply", 2).invoke(Vector3.field("upVector").value, 4 + Math.random() * 6));
          }
        } catch (e) {}
      }
      logV("[OP] spam fx burst");
    } catch (e) {
      console.log("[OP] spam fx failed: " + e);
    }
  }

  function stealCarryFrom(target: any) {
    if (!target) return;
    try {
      const local = getLocalRoot();
      if (!local) return;
      const myPos = local.method("get_position").invoke();
      // pull every nearby rigidbody / network object toward us — effective "steal what they're holding"
      const rbs = toJsArray(Object.method("FindObjectsOfType", 0).inflate(Rigidbody).invoke());
      let stole = 0;
      const tPos = getTransform(target).method("get_position").invoke();
      for (let i = 0; i < rbs.length; i++) {
        try {
          const rb = rbs[i];
          if (!rb || rb.isNull()) continue;
          const tr = getTransform(rb);
          if (!tr || tr.isNull()) continue;
          const p = tr.method("get_position").invoke();
          const d = Vector3.method("Distance", 2).invoke(tPos, p);
          if (d > 2.5) continue; // only stuff near the target
          // yank to local player
          tr.method("set_position").invoke(
            Vector3.method("op_Addition", 2).invoke(myPos, Vector3.method("op_Multiply", 2).invoke(Vector3.field("forwardVector").value, 0.6))
          );
          setRBVelocity(rb, Vector3.field("zeroVector").value);
          stole++;
        } catch (e) {}
      }
      logV("[OP] steal carry yanked " + stole + " objects");
    } catch (e) {
      console.log("[OP] steal carry failed: " + e);
    }
  }

  // ---- self size / invis ----
  let selfScale = 1.0;
  let ghostOn = false;
  let savedRenderers: any[] = [];

  function setSelfSize(scale: number) {
    selfScale = scale;
    const p = resolvePlayer();
    if (!p || !p.obj) return;
    try {
      getTransform(p.obj).method("set_localScale").invoke([scale, scale, scale]);
      logV("[OP] self size " + scale);
    } catch (e) {
      console.log("[OP] self size failed: " + e);
    }
  }

  function setGhost(on: boolean) {
    ghostOn = on;
    const p = resolvePlayer();
    if (!p || !p.obj) return;

    // primary: scale ghost (always works)
    try {
      getTransform(p.obj).method("set_localScale").invoke(
        on ? [0.02, 0.02, 0.02] : [selfScale, selfScale, selfScale]
      );
    } catch (e) {
      console.log("[OP] ghost scale failed: " + e);
    }

    // secondary: try hide renderers
    try {
      if (on) {
        savedRenderers = [];
        let rends: any[] = [];
        try {
          rends = toJsArray(p.obj.method("GetComponentsInChildren", 1).inflate(Renderer).invoke(true));
        } catch (e) {
          try {
            rends = toJsArray(Object.method("FindObjectsOfType", 0).inflate(Renderer).invoke());
          } catch (e2) {}
        }
        for (let i = 0; i < rends.length; i++) {
          try {
            if (rends[i] && !rends[i].isNull()) {
              const en = rends[i].method("get_enabled").invoke();
              if (en) {
                savedRenderers.push(rends[i]);
                rends[i].method("set_enabled").invoke(false);
              }
            }
          } catch (e) {}
        }
        logV("[OP] ghost ON scale+renderers(" + savedRenderers.length + ")");
      } else {
        for (let i = 0; i < savedRenderers.length; i++) {
          try { savedRenderers[i].method("set_enabled").invoke(true); } catch (e) {}
        }
        savedRenderers = [];
        logV("[OP] ghost OFF");
      }
    } catch (e) {
      logV("[OP] ghost renderer pass: " + e);
    }
  }

  function fireActiveGun() {
    if (!activeGun) return;
    if (gunCooldown > 0) return;
    // teleport guns aim at world, not players
    if (activeGun === "tpself") {
      gunCooldown = 0.3;
      logV("[OP] FIRE teleport gun");
      teleportGunFire();
      return;
    }
    if (activeGun === "tpall") {
      gunCooldown = 0.45;
      logV("[OP] FIRE teleport everyone");
      teleportEveryoneToLaser();
      return;
    }
    const all = getAllPlayerTargets();
    const target = aimPlayer(40.0);
    if (!target) {
      logV("[OP] no target — players scanned=" + all.length + " (need someone else in range)");
      return;
    }
    gunCooldown = 0.25;
    logV("[OP] FIRE " + activeGun + " → target ok (scanned " + all.length + ")");
    if (activeGun === "fly") flyGunTarget(target);
    else if (activeGun === "kick") kickTarget(target);
    else if (activeGun === "crash") crashTarget(target);
    else if (activeGun === "black") blackScreenTarget(target);
    else if (activeGun === "fling") flingTarget(target, 55);
    else if (activeGun === "pull") pullTarget(target, 45);
    else if (activeGun === "sizebig") sizeTarget(target, 3.0);
    else if (activeGun === "sizesmall") sizeTarget(target, 0.25);
    else if (activeGun === "spam") spamFxTarget(target);
    else if (activeGun === "steal") stealCarryFrom(target);
    else if (activeGun === "lockedmenu") giveLockedMenu(target);
  }

  function setGun(name: string) {
    activeGun = activeGun === name ? "" : name;
    if (!activeGun) destroyLaser();
    logV("[OP] gun = " + (activeGun || "none") + (activeGun ? " — laser ON, pull trigger to fire" : ""));
  }

  // ——— gun laser beam (visible aim) ———
  let laserObj: any = null;
  const LASER_LEN = 14.0;
  const LASER_THICK = 0.045; // thick blue beam
  const LASER_COLOR: [number, number, number, number] = [0.15, 0.55, 1.0, 1.0];

  function destroyLaser() {
    if (laserObj != null) {
      try { Destroy(laserObj); } catch (_) {}
      laserObj = null;
    }
  }

  function updateGunLaser() {
    if (!activeGun) {
      destroyLaser();
      return;
    }
    const hand = handTransform(false) || handTransform(true);
    if (!hand) {
      destroyLaser();
      return;
    }
    try {
      const origin = hand.method("get_position").invoke();
      const dir = handAimDir(hand);
      const rot = hand.method("get_rotation").invoke();
      const mid = Vector3.method("op_Addition", 2).invoke(
        origin,
        Vector3.method("op_Multiply", 2).invoke(dir, LASER_LEN * 0.5)
      );
      if (laserObj == null) {
        laserObj = createObject(mid, rot, [LASER_THICK, LASER_THICK, LASER_LEN], 3, LASER_COLOR);
        try {
          const col = getComponent(laserObj, BoxCollider);
          if (col) col.method("set_enabled").invoke(false);
        } catch (_) {}
        try {
          const r = getComponent(laserObj, Renderer);
          const mat = r.method("get_material").invoke();
          if (MenuShader && !MenuShader.isNull()) mat.method("set_shader").invoke(MenuShader);
          mat.method("set_color").invoke(LASER_COLOR);
        } catch (_) {}
      } else {
        const t = getTransform(laserObj);
        t.method("set_position").invoke(mid);
        t.method("set_rotation").invoke(rot);
        t.method("set_localScale").invoke([LASER_THICK, LASER_THICK, LASER_LEN]);
        try {
          const r = getComponent(laserObj, Renderer);
          r.method("get_material").invoke().method("set_color").invoke(LASER_COLOR);
        } catch (_) {}
      }
    } catch (e) {}
  }

  // Force pickup — yank nearby world items to your hands continuously while on
  let fpRbCache: any[] = [];
  let fpRbScanAt = 0;
  function forcePickupTick() {
    if (!forcePickupOn) return;
    try {
      const local = getLocalRoot();
      if (!local) return;
      const myPos = local.method("get_position").invoke();
      const hand = handTransform(false);
      const dest = hand ? hand.method("get_position").invoke() : myPos;
      const nowFp = Date.now();
      if (nowFp - fpRbScanAt > 300) {
        fpRbCache = toJsArray(Object.method("FindObjectsOfType", 0).inflate(Rigidbody).invoke());
        fpRbScanAt = nowFp;
      }
      const rbs = fpRbCache;
      for (let i = 0; i < rbs.length; i++) {
        try {
          const rb = rbs[i];
          if (!rb || rb.isNull()) continue;
          const tr = getTransform(rb);
          if (!tr || tr.isNull()) continue;
          const p = tr.method("get_position").invoke();
          const d = Vector3.method("Distance", 2).invoke(myPos, p);
          if (d > 4.0 || d < 0.15) continue;
          // pull item toward hand
          const to = Vector3.method("op_Subtraction", 2).invoke(dest, p);
          const dir = Vector3.method("Normalize", 1).invoke(to);
          setRBVelocity(rb, Vector3.method("op_Multiply", 2).invoke(dir, 8.0));
        } catch (e) {}
      }
    } catch (e) {}
  }

  function setForcePickup(on: boolean) {
    forcePickupOn = on;
    logV("[OP] force pickup " + (on ? "ON" : "OFF"));
  }

  function clearLockedMenus() {
    for (let i = 0; i < lockedMenuObjects.length; i++) {
      try { Destroy(lockedMenuObjects[i]); } catch (e) {}
    }
    lockedMenuObjects = [];
    logV("[OP] cleared locked menus / black walls / fx");
  }

  interface ItemEntry {
    id: string;
    label: string;
    family: number;
  }

  let itemList: ItemEntry[] = [];
  let itemsLoaded = false;
  let spawnSeq = 0;
  let selectedItem: ItemEntry | null = null;
  let spawn1000x = false;


  let spawnQueue = 0;
  const SPAWN_PER_TICK = 20;

  function queueSpawn(count: number) {
    if (!selectedItem) {
      console.log("[Spawn] no item selected - click one in the Item Spawning tab");
      return;
    }
    spawnQueue += count;
    console.log("[Spawn] queued " + count + " x " + selectedItem.id + " (total " + spawnQueue + ")");
  }

  function drainSpawnQueue() {
    if (spawnQueue <= 0) return;
    if (!selectedItem) {
      spawnQueue = 0;
      return;
    }
    const entry = selectedItem;
    let n = 0;
    while (spawnQueue > 0 && n < SPAWN_PER_TICK) {
      spawnItem(entry, true);
      spawnQueue--;
      n++;
    }
  }

  function spawnSelected(count?: number) {
    if (!selectedItem) {
      console.log("[Spawn] no item selected - click one in the Item Spawning tab");
      return;
    }
    if (count && count > 1) {
      queueSpawn(count);
      return;
    }
    console.log("[Spawn] grip -> " + selectedItem.id);
    spawnItem(selectedItem);
  }

  function selectItem(entry: ItemEntry) {
    selectedItem = entry;
    logV("[mestro] selected " + entry.id);
  }


  const FAM_SEED = 0;
  const FAM_PRODUCE = 1;
  const FAM_ORE = 2;
  const FAM_WOOD = 3;
  const FAM_LAND = 4;
  const FAM_GEAR = 5;
  const FAM_WEAPON = 6;
  const FAM_WATERINGCAN = 7;
  const FAM_FERTILIZER = 8;
  const FAM_LIGHTNING = 9;
  const FAM_SPRINKLER = 10;
  const FAM_DJBOOTH = 11;
  const FAM_LANDMINE = 12;
  const FAM_EGG = 13;
  const FAM_CREATURE = 14;
  const FAM_TROWEL = 15;
  const FAM_LANDMOVER = 16;
  const FAM_WEATHERSTAFF = 17;

  const ALL_FAMILIES = [
    FAM_SEED, FAM_LAND, FAM_GEAR, FAM_EGG, FAM_PRODUCE, FAM_ORE, FAM_WOOD,
    FAM_WEAPON, FAM_WATERINGCAN, FAM_FERTILIZER, FAM_LIGHTNING, FAM_SPRINKLER,
    FAM_DJBOOTH, FAM_LANDMINE, FAM_CREATURE, FAM_TROWEL, FAM_LANDMOVER, FAM_WEATHERSTAFF
  ];

  const seenIds: { [k: string]: boolean } = {};

  function addItem(id: string, label: string, family: number) {
    if (!id) return;
    if (seenIds[id]) return;
    seenIds[id] = true;
    itemList.push({ id: id, label: label || id, family: family });
  }

  function getCarryRegistry() {
    try {
      const r = CarryRegistryClass.method("EnsureInstance").invoke();
      if (r && !r.isNull()) return r;
    } catch (e) {
      console.log("[Items] EnsureInstance failed: " + e);
    }
    return null;
  }

  function collectRegistry(registryHost: any, field: string, resolver: string, dataField: string, family: number) {
    if (!registryHost) return;
    let reg = null;
    try {
      reg = registryHost.field(field).value;
      if (!reg || reg.isNull()) reg = null;
    } catch (e) {}
    if (!reg) {
      try {
        reg = registryHost.method(resolver).invoke();
      } catch (e) {}
    }
    if (!reg || reg.isNull()) return;

    let list = null;
    try {
      list = reg.method("get_Entries").invoke();
    } catch (e) {
      try {
        list = reg.field("entries").value;
      } catch (e2) {}
    }
    if (!list || list.isNull()) return;

    let n = 0;
    try {
      n = listCount(list);
    } catch (e) {
      return;
    }

    for (let i = 0; i < n; i++) {
      try {
        const entry = listAt(list, i);
        if (!entry || entry.isNull()) continue;
        const data = entry.field(dataField).value;
        if (!data || data.isNull()) continue;
        const id = strOf(data, "itemId") || strOf(data, "critterId");
        if (!id) continue;
        const label = strOf(data, "gearName") || strOf(data, "displayName") || id;
        addItem(id, label, family);
      } catch (e) {}
    }
  }

  function collectList(list: any, family: number) {
    let n = 0;
    try {
      n = listCount(list);
    } catch (e) {
      return;
    }

    for (let i = 0; i < n; i++) {
      try {
        const entry = listAt(list, i);
        if (!entry || entry.isNull()) continue;
        const id = strOf(entry, "itemId") || strOf(entry, "critterId");
        if (!id) continue;
        const label = strOf(entry, "displayName") || strOf(entry, "gearName") || id;
        addItem(id, label, family);
      } catch (e) {}
    }
  }

  function collectDirect(obj: any, family: number) {
    try {
      const id = strOf(obj, "itemId") || strOf(obj, "critterId");
      if (!id) return;
      const label = strOf(obj, "displayName") || strOf(obj, "gearName") || id;
      addItem(id, label, family);
    } catch (e) {}
  }


  function collectDataset(klass: any, family: number) {
    if (!klass) return;
    const objects = assetInstances(klass);

    for (let i = 0; i < objects.length; i++) {
      const obj = objects[i];
      if (!obj || obj.isNull()) continue;
      let all = null;
      try {
        all = obj.method("get_All").invoke();
      } catch (e) {}
      if (all && !all.isNull()) collectList(all, family);
      else collectDirect(obj, family);
    }
  }

  const KEEP_ITEMS: string[] = [
    "Dream Bloom", "Burning Buds", "GROLD", "Venus Fly Trap", "Blood Banana", "Banana",
    "Fuchsia", "Mango", "Rocket Corn", "Donut Seed", "Charity Seed",
    "Spooky Mushroom", "Spooky Beanstalk", "Candy Corn", "Mythic Mummy"
  ];
  // always removed from the item spawner, even if they show up in the game's list
  const REMOVE_ITEMS: string[] = [
    "Watermelon", "Starfruit", "Papaya", "Dragon Fruit", "Pineapple",
    "Daisy", "Sunflower", "Carrot", "Tomato", "Blueberry", "Strawberry", "Kiwi", "Peashooter"
  ];
  function normName(s: string): string {
    return (s || "").toLowerCase().replace(/[^a-z0-9]/g, "");
  }

  function buildItemList() {
    itemList = [];
    for (const k in seenIds) delete seenIds[k];

    const host = getCarryRegistry();

    const step = (tag: string, run: () => void) => {
      const before = itemList.length;
      try {
        run();
      } catch (e) {
        console.log("[Items] " + tag + " threw: " + e);
      }
      const added = itemList.length - before;
      if (added > 0) console.log("[Items] " + tag + " +" + added);
    };

    // shop registries - the ids that are directly spawnable
    step("seedShop", () => collectRegistry(host, "seedShopRegistry", "ResolveSeedShopRegistry", "plantData", FAM_SEED));
    step("gearShop", () => collectRegistry(host, "gearShopRegistry", "ResolveGearShopRegistry", "gearData", FAM_GEAR));
    step("eggShop", () => collectRegistry(host, "eggShopRegistry", "ResolveEggShopRegistry", "eggType", FAM_EGG));
    step("landShop", () => collectRegistry(host, "landShopRegistry", "ResolveLandShopRegistry", "landData", FAM_LAND));

    // databases - every item id in the game
    step("plants", () => collectDataset(PlantDatabaseClass, FAM_SEED));
    step("gear", () => collectDataset(GearDatabaseClass, FAM_GEAR));
    step("land", () => collectDataset(LandDatabaseClass, FAM_LAND));
    step("eggs", () => collectDataset(EggDatabaseClass, FAM_EGG));
    step("fish", () => collectDataset(FishDatabaseClass, FAM_PRODUCE));
    step("critters", () => collectDataset(CritterDatabaseClass, FAM_CREATURE));
    step("creatures", () => collectDataset(CreatureDatabaseClass, FAM_CREATURE));
    step("ore", () => collectDataset(OreDataSOClass, FAM_ORE));
    step("wood", () => collectDataset(WoodDataSOClass, FAM_WOOD));

    itemList.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
    // keep only the requested fruits and seeds (basic fruits are dropped)
    const keepNorm = KEEP_ITEMS.map(normName);
    const keptList = itemList.filter((e) => {
      const n = normName(e.label || "");
      const i = normName(e.id || "");
      return keepNorm.some((k) => n === k || i === k || n.indexOf(k) >= 0 || i.indexOf(k) >= 0);
    });
    const missing: string[] = [];
    for (let k = 0; k < KEEP_ITEMS.length; k++) {
      const kn = normName(KEEP_ITEMS[k]);
      const hit = keptList.some((e) => normName(e.label || "").indexOf(kn) >= 0 || normName(e.id || "").indexOf(kn) >= 0);
      if (!hit) missing.push(KEEP_ITEMS[k]);
    }
    const removeNorm = REMOVE_ITEMS.map(normName);
    const finalList = keptList.filter((e) => {
      const n = normName(e.label || "");
      const i = normName(e.id || "");
      if (removeNorm.some((k) => n === k || i === k)) {
        console.log("[Items] removed: " + (e.label || e.id));
        return false;
      }
      // seeds must match a keep name exactly, so a basic seed can't slip through a partial match
      if (e.family === FAM_SEED) {
        const exact = keepNorm.some((k) => n === k || i === k);
        if (!exact) {
          console.log("[Items] removed basic seed: " + (e.label || e.id));
          return false;
        }
      }
      return true;
    });
    itemList = finalList;
    console.log("[Items] kept " + itemList.length + " of the requested items; not found in game: " + (missing.join(", ") || "none"));
    itemsLoaded = true;
    console.log("[Items] scanned " + itemList.length + " item ids");
    for (let i = 0; i < itemList.length; i++) {
      const e = itemList[i];
      console.log("[ItemList] " + (i + 1) + ". " + e.id + " | " + e.label + " | " + e.family);
    }
  }

  function pushItemButtons() {
    for (let i = 0; i < itemList.length; i++) {
      const entry = itemList[i];
      buttons[CAT_ITEMS].push(
        new ButtonInfo({
          buttonText: entry.label + "  [" + entry.id + "]",
          keepOn: false,
          item: entry,
          reload: false,
          method: () => selectItem(entry)
        })
      );
    }
  }

  function ensureItems() {
    if (itemsLoaded) return;
    buildItemList();
    pushItemButtons();
  }

  function rescanItems() {
    itemsLoaded = false;
    selectedItem = null;
    buttons[CAT_ITEMS] = buttons[CAT_ITEMS].slice(0, ITEM_BUTTONS_FIXED);
    currentPage = 0;
    ensureItems();
  }


  function spawnPosition() {
    const rightHand = handTransform(false);
    if (rightHand) {
      try {
        return rightHand.method("get_position").invoke();
      } catch (e) {}
    }
    const p = resolvePlayer();
    if (p && p.head && !p.head.isNull()) {
      try {
        const t = getTransform(p.head);
        const pos = t.method("get_position").invoke();
        const fwd = t.method("get_forward").invoke();
        return Vector3.method("op_Addition", 2).invoke(pos, Vector3.method("op_Multiply", 2).invoke(fwd, 0.7));
      } catch (e) {}
    }
    return [0.0, 1.2, 0.0];
  }

  function spawnItem(entry: ItemEntry, quiet?: boolean) {
    try {
      const host = getCarryRegistry();
      if (!host) {
        console.log("[Spawn] no PlayerCarryItemRegistry");
        return;
      }
      const runner = getRunner();
      if (!runner) {
        console.log("[Spawn] no NetworkRunner - join a room first");
        return;
      }

      ensureItems();

      const pos = spawnPosition();
      const order = [entry.family].concat(ALL_FAMILIES.filter((f) => f !== entry.family));
      let lastErr = "";

      for (let i = 0; i < order.length; i++) {
        const fam = order[i];
        try {
          const payload = CarryRegistryClass.method("CreatePayload", 4).invoke(
            fam,
            Il2Cpp.string(entry.id),
            1,
            Il2Cpp.string("mestro" + spawnSeq++)
          );
          if (!payload || payload.isNull()) continue;

          const spawnedRef = makeRef(NetworkObjectClass.type);
          const failRef = makeRef(StringClass.type);

          const ok = host
            .method("TryRestoreToWorld", 6)
            .invoke(payload, runner, pos, identityQuaternion, spawnedRef, failRef);

          const err = refString(failRef);
          if (err) lastErr = err;

          if (ok) {
            if (!quiet) console.log("[Spawn] OK " + entry.id + " (family " + fam + ")");
            // diagnostic: is the spawned object actually networked? IsSpawned=false means
            // only you can see it, which is why other players can't grab it
            try {
              const no = spawnedRef.value;
              if (no && !no.isNull()) {
                let isSpawned = "?";
                let nid = "?";
                try { isSpawned = String(no.method("get_IsSpawned").invoke()); } catch (_) {}
                try { nid = String(no.method("get_Id").invoke()); } catch (_) {}
                console.log("[Spawn] networked object id=" + nid + " IsSpawned=" + isSpawned + " for " + entry.id);
              } else {
                console.log("[Spawn] WARNING no NetworkObject returned for " + entry.id + " (local only)");
              }
            } catch (e) {
              console.log("[Spawn] networked check failed: " + e);
            }
            return;
          }
        } catch (e) {
          lastErr = String(e);
        }
      }


      if (!quiet) console.log("[Spawn] FAILED " + entry.id + " -> " + (lastErr || "unknown"));
    } catch (e) {
      console.log("[Spawn] error " + entry.id + ": " + e);
    }
  }

