  function growAllSeeds() {
    const plots = scanFarmComponents(NetworkFarmPlotClass, "NetworkFarmPlot");
    const farms = scanFarmComponents(NetworkFarmClass, "NetworkFarm");
    const views = scanFarmComponents(PlantViewClass, "PlantView");

    let okPlots = 0;
    for (let i = 0; i < plots.length; i++) {
      try {
        plots[i].method("UpdateAllPlantsGrowth").invoke();
        okPlots++;
      } catch (e) {}
    }

    let okFarms = 0;
    for (let i = 0; i < farms.length; i++) {
      try {
        farms[i].method("UpdatePlantGrowthStates").invoke();
        okFarms++;
      } catch (e) {}
    }


    for (let pump = 0; pump < 25; pump++) {
      for (let i = 0; i < plots.length; i++) {
        try {
          plots[i].method("UpdateAllPlantsGrowth").invoke();
        } catch (e) {}
      }
      for (let i = 0; i < farms.length; i++) {
        try {
          farms[i].method("UpdatePlantGrowthStates").invoke();
        } catch (e) {}
      }
    }

    logV("[Grow] pumped plots=" + okPlots + "/" + plots.length +
      " farms=" + okFarms + "/" + farms.length + " views=" + views.length);
  }

