  // ===================== SOUNDBOARD (.wav only) =====================
  // Folder (Quest): Android/data/com.FeelGoodGames.GRO/files/soundbored
  const SOUNDBOARD_DIRS = [
    "/sdcard/Android/data/com.FeelGoodGames.GRO/files/soundbored",
    "/storage/emulated/0/Android/data/com.FeelGoodGames.GRO/files/soundbored",
    "/sdcard/Android/data/com.FeelGoodGames.GRO/files/Soundbored",
    "/sdcard/Android/data/com.FeelGoodGames.GRO/files/soundboard"
  ];

  let soundboardClips: { name: string; path: string }[] = [];
  let soundboardAudioSrc: any = null;
  let lastNetSound = "";
  let lastNetSoundAt = 0;

  function listWavFiles(): { name: string; path: string }[] {
    const out: { name: string; path: string }[] = [];
    try {
      if (typeof Java === "undefined" || !Java.available) return out;
      Java.perform(() => {
        const File = Java.use("java.io.File");
        for (let d = 0; d < SOUNDBOARD_DIRS.length; d++) {
          try {
            const dir = File.$new(SOUNDBOARD_DIRS[d]);
            if (!dir.exists() || !dir.isDirectory()) continue;
            const files = dir.listFiles();
            if (!files) continue;
            for (let i = 0; i < files.length; i++) {
              const f = files[i];
              const nm = String(f.getName());
              if (!nm.toLowerCase().endsWith(".wav")) continue;
              out.push({ name: nm.replace(/\.wav$/i, ""), path: String(f.getAbsolutePath()) });
            }
            if (out.length > 0) {
              logV("[Soundboard] folder " + SOUNDBOARD_DIRS[d] + " → " + out.length + " wav");
              break;
            }
          } catch (e) {}
        }
      });
    } catch (e) {
      console.log("[Soundboard] list failed: " + e);
    }
    return out;
  }

  function readFileBytesJava(path: string): number[] | null {
    let out: number[] | null = null;
    try {
      Java.perform(() => {
        try {
          const File = Java.use("java.io.File");
          const fis = Java.use("java.io.FileInputStream").$new(File.$new(path));
          const len = Number(File.$new(path).length());
          if (len <= 44 || len > 12 * 1024 * 1024) {
            fis.close();
            return;
          }
          const buf = Java.array("byte", Array(Math.min(65536, len)).fill(0));
          const bytes: number[] = [];
          let read = 0;
          while (read < len) {
            const n = fis.read(buf);
            if (n <= 0) break;
            for (let j = 0; j < n; j++) {
              let v = buf[j];
              if (v < 0) v += 256;
              bytes.push(v);
            }
            read += n;
          }
          fis.close();
          out = bytes;
        } catch (e) {
          console.log("[Soundboard] read " + path + " failed: " + e);
        }
      });
    } catch (e) {
      logV("[Soundboard] java read: " + e);
    }
    return out;
  }

  function u16(b: number[], i: number) {
    return b[i] | (b[i + 1] << 8);
  }
  function u32(b: number[], i: number) {
    return (b[i] | (b[i + 1] << 8) | (b[i + 2] << 16) | (b[i + 3] << 24)) >>> 0;
  }

  function wavToAudioClip(name: string, bytes: number[]): any {
    if (!AudioClip || bytes.length < 44) return null;
    // RIFF header
    if (bytes[0] !== 0x52 || bytes[1] !== 0x49 || bytes[2] !== 0x46 || bytes[3] !== 0x46) {
      logV("[Soundboard] not RIFF: " + name);
      return null;
    }
    let offset = 12;
    let audioFormat = 1;
    let channels = 1;
    let sampleRate = 44100;
    let bitsPerSample = 16;
    let dataStart = -1;
    let dataSize = 0;
    while (offset + 8 <= bytes.length) {
      const id = String.fromCharCode(bytes[offset], bytes[offset + 1], bytes[offset + 2], bytes[offset + 3]);
      const size = u32(bytes, offset + 4);
      if (id === "fmt ") {
        audioFormat = u16(bytes, offset + 8);
        channels = u16(bytes, offset + 10);
        sampleRate = u32(bytes, offset + 12);
        bitsPerSample = u16(bytes, offset + 22);
      } else if (id === "data") {
        dataStart = offset + 8;
        dataSize = size;
        break;
      }
      offset += 8 + size + (size % 2);
    }
    if (dataStart < 0 || audioFormat !== 1) {
      logV("[Soundboard] need PCM wav (fmt=1): " + name + " fmt=" + audioFormat);
      return null;
    }
    const bytesPerSample = bitsPerSample / 8;
    const sampleCount = Math.floor(dataSize / (bytesPerSample * channels));
    if (sampleCount < 1) return null;

    // float samples interleaved
    const floats: number[] = new Array(sampleCount * channels);
    for (let s = 0; s < sampleCount * channels; s++) {
      const i = dataStart + s * bytesPerSample;
      if (bitsPerSample === 16) {
        let v = u16(bytes, i);
        if (v >= 0x8000) v -= 0x10000;
        floats[s] = v / 32768.0;
      } else if (bitsPerSample === 8) {
        floats[s] = (bytes[i] - 128) / 128.0;
      } else {
        floats[s] = 0;
      }
    }

    try {
      // AudioClip.Create(name, lengthSamples, channels, frequency, stream)
      const clip = AudioClip.method("Create", 5).invoke(
        Il2Cpp.string(name),
        sampleCount,
        channels,
        sampleRate,
        false
      );
      if (!clip || clip.isNull()) return null;
      const arr = Il2Cpp.array(Il2Cpp.corlib.class("System.Single"), floats);
      // SetData(float[] data, int offsetSamples)
      try {
        clip.method("SetData", 2).invoke(arr, 0);
      } catch (e) {
        try { clip.method("SetData", 1).invoke(arr); } catch (e2) {
          console.log("[Soundboard] SetData failed: " + e2);
          return null;
        }
      }
      return clip;
    } catch (e) {
      console.log("[Soundboard] AudioClip.Create failed: " + e);
      return null;
    }
  }

  let soundboardVolume = 1.0;
  let soundboardMediaPlayer: any = null;

  function ensureSoundSource(): any {
    if (soundboardAudioSrc && !soundboardAudioSrc.isNull()) return soundboardAudioSrc;
    try {
      const p = resolvePlayer();
      const host = p && p.obj ? p.obj : null;
      let go: any = null;
      if (host) {
        try { go = host.method("get_gameObject").invoke(); } catch (_) {}
      }
      if (!go || go.isNull()) {
        go = GameObject.new();
        try { go.method("set_name").invoke(Il2Cpp.string("mestro_soundboard")); } catch (_) {}
      }
      soundboardAudioSrc = addComponent(go, AudioSource);
      if (soundboardAudioSrc && !soundboardAudioSrc.isNull()) {
        try { soundboardAudioSrc.method("set_playOnAwake").invoke(false); } catch (_) {}
        try { soundboardAudioSrc.method("set_spatialBlend").invoke(1.0); } catch (_) {}
        try { soundboardAudioSrc.method("set_volume").invoke(soundboardVolume); } catch (_) {}
        try { soundboardAudioSrc.method("set_maxDistance").invoke(80.0); } catch (_) {}
        try { soundboardAudioSrc.method("set_rolloffMode").invoke(1); } catch (_) {}
        console.log("[Soundboard] AudioSource ready");
      }
    } catch (e) {
      logV("[Soundboard] AudioSource create: " + e);
    }
    return soundboardAudioSrc;
  }

  function applySoundboardVolume() {
    try {
      const src = ensureSoundSource();
      if (src) src.method("set_volume").invoke(soundboardVolume);
    } catch (_) {}
    try {
      if (soundboardMediaPlayer) {
        Java.perform(() => {
          try { soundboardMediaPlayer.setVolume(soundboardVolume, soundboardVolume); } catch (_) {}
        });
      }
    } catch (_) {}
    logV("[Soundboard] volume " + Math.round(soundboardVolume * 100) + "%");
  }

  function stopSoundboard() {
    try {
      if (soundboardAudioSrc && !soundboardAudioSrc.isNull()) {
        try { soundboardAudioSrc.method("Stop", 0).invoke(); } catch (_) {}
      }
    } catch (_) {}
    try {
      Java.perform(() => {
        try {
          if (soundboardMediaPlayer) {
            soundboardMediaPlayer.stop();
            soundboardMediaPlayer.release();
            soundboardMediaPlayer = null;
          }
        } catch (_) {}
      });
    } catch (_) {}
    logV("[Soundboard] STOP");
  }

  function playWavLocal(path: string, name: string) {
    try {
      const bytes = readFileBytesJava(path);
      if (!bytes) {
        logV("[Soundboard] could not read " + path);
        return;
      }
      const clip = wavToAudioClip(name, bytes);
      if (!clip) {
        // fallback: Android MediaPlayer (local only)
        try {
          Java.perform(() => {
            const mp = Java.use("android.media.MediaPlayer").$new();
            mp.setDataSource(path);
            mp.prepare();
            mp.start();
            logV("[Soundboard] MediaPlayer → " + name);
          });
        } catch (e) {
          console.log("[Soundboard] MediaPlayer failed: " + e);
        }
        return;
      }
      const src = ensureSoundSource();
      if (!src) return;
      try {
        src.method("set_volume").invoke(soundboardVolume);
        src.method("set_clip").invoke(clip);
        src.method("Play", 0).invoke();
        logV("[Soundboard] PLAY → " + name + " vol=" + Math.round(soundboardVolume * 100) + "%");
      } catch (e) {
        try {
          src.method("PlayOneShot", 2).invoke(clip, soundboardVolume);
          logV("[Soundboard] PlayOneShot → " + name);
        } catch (e2) {
          console.log("[Soundboard] play failed: " + e2);
        }
      }
    } catch (e) {
      logV("[Soundboard] playWavLocal: " + e);
    }
  }

  function playWavNetworkHint(name: string) {
    // Session-wide hint so other mestro clients in the same room can pick it up
    lastNetSound = name;
    lastNetSoundAt = Date.now();
    try {
      const runner = getRunner();
      if (!runner) return;
      // best-effort: SessionName / custom properties not always writable mid-session
      try {
        runner.method("SessionInfo"); // probe
      } catch (_) {}
      logV("[Soundboard] room cue → " + name + " (others with mestro_ac + same wav hear it)");
    } catch (e) {}
  }

