  function createSoundboardFolder() {
    let created = "";
    let err = "";
    try {
      if (typeof Java === "undefined" || !Java.available) {
        logV("[Soundboard] Java not available — can't mkdir");
        return;
      }
      Java.perform(() => {
        const File = Java.use("java.io.File");
        // primary path first
        const paths = SOUNDBOARD_DIRS.slice();
        for (let i = 0; i < paths.length; i++) {
          try {
            const dir = File.$new(paths[i]);
            if (dir.exists() && dir.isDirectory()) {
              created = paths[i] + " (already exists)";
              break;
            }
            // mkdirs creates parents too
            const ok = dir.mkdirs();
            if (ok || (dir.exists() && dir.isDirectory())) {
              // write a readme so the folder is visible when browsing
              try {
                const readme = File.$new(dir, "PUT_WAV_FILES_HERE.txt");
                const fos = Java.use("java.io.FileOutputStream").$new(readme);
                const msg = "mestro soundboard\nDrop .wav (PCM) files in this folder.\nThen in-game: Soundboard → Refresh WAVs\n";
                fos.write(Java.use("java.lang.String").$new(msg).getBytes("UTF-8"));
                fos.close();
              } catch (_) {}
              created = paths[i];
              break;
            }
          } catch (e) {
            err = String(e);
          }
        }
      });
    } catch (e) {
      err = String(e);
    }
    if (created) {
      console.log("[Soundboard] folder ready:");
      logV("  " + created);
    } else {
      console.log("[Soundboard] mkdir failed: " + (err || "unknown"));
      logV("[Soundboard] try creating manually:");
      logV("  Android/data/com.FeelGoodGames.GRO/files/soundbored/");
    }
  }

